use std::cmp::Ordering;

// Define the structure for a binary search tree node
struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

// Function to insert a new value into the binary search tree
fn insert(root: &mut Option<Box<Node>>, value: i32) {
    if let Some(node) = root {
        match value.cmp(&node.value) {
            Ordering::Less => insert(&mut node.left, value),
            Ordering::Greater => insert(&mut node.right, value),
            _ => {
                // If the value is equal, insert it as a duplicate in the left subtree
                insert(&mut node.left, value);
            }
        }
    } else {
        *root = Some(Box::new(Node {
            value,
            left: None,
            right: None,
        }));
    }
}

// Function to find the lowest common ancestor in the binary search tree
fn lowest_common_ancestor(root: &Option<Box<Node>>, v1: i32, v2: i32) -> Option<i32> {
    if let Some(node) = root {
        let value = node.value;
        match (v1.cmp(&value), v2.cmp(&value)) {
            (Ordering::Less, Ordering::Less) => lowest_common_ancestor(&node.left, v1, v2),
            (Ordering::Greater, Ordering::Greater) => lowest_common_ancestor(&node.right, v1, v2),
            _ => Some(value),
        }
    } else {
        None
    }
}

fn main() {
    // Create a binary search tree with some duplicate values
    let mut root = None;
    insert(&mut root, 5);
    insert(&mut root, 2);
    insert(&mut root, 8);
    insert(&mut root, 2);
    insert(&mut root, 7);
    insert(&mut root, 10);
    insert(&mut root, 1);
    insert(&mut root, 3);
    insert(&mut root, 2);
    insert(&mut root, 6);
    insert(&mut root, 9);

    // Find the lowest common ancestor of two values
    let v1 = 2;
    let v2 = 10;
    if let Some(ancestor) = lowest_common_ancestor(&root, v1, v2) {
        println!("Lowest Common Ancestor: {}", ancestor);
    } else {
        println!("No common ancestor found");
    }
}

