use std::collections::HashMap;

fn are_anagrams(s1: &str, s2: &str) -> bool {
    // Create a helper function to normalize a string by removing special characters and white spaces
    let normalize_string = |s: &str| {
        s.chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect::<String>()
    };

    // Normalize the input strings
    let s1_normalized = normalize_string(s1);
    let s2_normalized = normalize_string(s2);

    // Create character frequency maps for each normalized string
    let mut freq_map1: HashMap<char, u32> = HashMap::new();
    let mut freq_map2: HashMap<char, u32> = HashMap::new();

    // Populate the frequency maps
    for c in s1_normalized.chars() {
        *freq_map1.entry(c).or_insert(0) += 1;
    }

    for c in s2_normalized.chars() {
        *freq_map2.entry(c).or_insert(0) += 1;
    }

    // Compare the frequency maps
    freq_map1 == freq_map2
}

fn main() {
    let s1 = "Listen";
    let s2 = "Silent";

    let are_anagrams = are_anagrams(s1, s2);
    println!("Are '{}' and '{}' anagrams? {}", s1, s2, are_anagrams);
}

