pub fn is_palindrome_with_special_char(input: &str) -> bool {
    let special_chars = ['!', '@', '#', '$', '%', '&', '*'];
    let input = input.chars().filter(|c| c.is_ascii_alphanumeric() || special_chars.contains(c)).collect::<String>();
    let input = input.to_lowercase();

    let reverse_input = input.chars().rev().collect::<String>();

    input == reverse_input && input.contains(|c| special_chars.contains(&c))
}

// Define a binary search tree node
struct TreeNode {
    value: i32,
    left: Option<Box<TreeNode>>,
    right: Option<Box<TreeNode>>,
}

// Function to create a new node
fn new_node(value: i32) -> Option<Box<TreeNode>> {
    Some(Box::new(TreeNode {
        value,
        left: None,
        right: None,
    }))
}

// Function to insert a new node into the binary search tree
fn insert(root: &mut Option<Box<TreeNode>>, value: i32) {
    if let Some(ref mut node) = root {
        if value < node.value {
            insert(&mut node.left, value);
        } else {
            insert(&mut node.right, value);
        }
    } else {
        *root = new_node(value);
    }
}

// Function to find the lowest common ancestor in a binary search tree
fn lowest_common_ancestor(root: &Option<Box<TreeNode>>, p: i32, q: i32) -> Option<i32> {
    if let Some(ref node) = root {
        if p < node.value && q < node.value {
            return lowest_common_ancestor(&node.left, p, q);
        }
        if p > node.value && q > node.value {
            return lowest_common_ancestor(&node.right, p, q);
        }
        return Some(node.value);
    }
    None
}

fn main() {
    // Create the binary search tree
    let mut root = None;
    insert(&mut root, 6);
    insert(&mut root, 2);
    insert(&mut root, 8);
    insert(&mut root, 0);
    insert(&mut root, 4);
    insert(&mut root, 7);
    insert(&mut root, 9);
    insert(&mut root, 3);
    insert(&mut root, 5);

    // Find the lowest common ancestor of nodes with values 2 and 4
    let lca = lowest_common_ancestor(&root, 2, 4);
