pub fn process_maybe_parallel_map_collect<'a, T, I, A, R>(
    items: I,
    action: A,
    hint_do_parallel: bool,
) -> Vec<R>
where
    T: 'a + Send,
    I: IntoParallelIterator<Item = T> + Send + 'a,
    A: Fn(T) -> R + Sync + Send + 'a,
    R: Send,
{
    if hint_do_parallel {
        items.into_par_iter().map(action).collect()
    } else {
        items.into_iter().map(action).collect()
    }
}

#[cfg(not(feature = "rayon"))]
