    items: I,
    action: A,
    _hint_do_parallel: bool,
) -> Vec<R>
where
    T: 'a + Send,
    I: Iterator<Item = T> + Send + 'a,
    A: Fn(T) -> R + Sync + Send + 'a,
    R: Send,
{
