use serde::{Serialize, Deserialize};
use std::fs;

#[derive(Serialize, Deserialize, PartialEq, Debug)]
struct Body {
    content: String,
}

fn save_and_load_json<T: Serialize + for<'de> Deserialize<'de>>(data: &T, file_path: &str) -> Result<(), String> {
    let json = serde_json::to_string(data).map_err(|e| format!("Serialization error: {}", e))?;
    fs::write(file_path, json).map_err(|e| format!("File write error: {}", e))?;

    let loaded_json = fs::read_to_string(file_path).map_err(|e| format!("File read error: {}", e))?;
    let loaded_data: T = serde_json::from_str(&loaded_json).map_err(|e| format!("Deserialization error: {}", e))?;

    if *data != loaded_data {
        return Err("Data mismatch after save and load".to_string());
    }

    Ok(())
}

fn main() {
    let data = Body { content: "Sol".to_string() };
    let file_path = "test.json";
    match save_and_load_json(&data, file_path) {
        Ok(()) => println!("Save and load successful"),
        Err(err) => eprintln!("Error: {}", err),
    }
}

