// Define a data structure to represent a message
struct Message {
    sender_id: u32,
    recipient_id: u32,
    label: String,
    timestamp: f64,
}

// Implement a message passing system
struct MessageSystem {
    messages: Vec<Message>,
}

impl MessageSystem {
    // Method to add a new message to the system
    fn add_message(&mut self, sender_id: u32, recipient_id: u32, label: String, timestamp: f64) {
        let message = Message {
            sender_id,
            recipient_id,
            label,
            timestamp,
        };
        self.messages.push(message);
    }

    // Method to retrieve all messages sent from a specific sender, sorted by timestamp
    fn get_messages_sent_by_sender(&self, sender_id: u32) -> Vec<&Message> {
        let mut sent_messages: Vec<&Message> = self.messages.iter()
            .filter(|message| message.sender_id == sender_id)
            .collect();
        sent_messages.sort_by(|a, b| a.timestamp.partial_cmp(&b.timestamp).unwrap());
        sent_messages
    }

    // Method to retrieve all messages received by a specific recipient, sorted by timestamp
    fn get_messages_received_by_recipient(&self, recipient_id: u32) -> Vec<&Message> {
        let mut received_messages: Vec<&Message> = self.messages.iter()
            .filter(|message| message.recipient_id == recipient_id)
            .collect();
        received_messages.sort_by(|a, b| a.timestamp.partial_cmp(&b.timestamp).unwrap());
        received_messages
    }
}

fn main() {
    // Create a message system instance
    let mut message_system = MessageSystem { messages: Vec::new() };

    // Add sample messages to the system
    message_system.add_message(1, 2, String::from("Hello"), 1.5);
    message_system.add_message(2, 1, String::from("Hi"), 2.0);
    message_system.add_message(1, 3, String::from("Meeting"), 1.0);

    // Retrieve and print messages sent by a specific sender
    let sender_id = 1;
    let sent_messages = message_system.get_messages_sent_by_sender(sender_id);
    println!("Messages sent by sender {}: {:?}", sender_id, sent_messages);

    // Retrieve and print messages received by a specific recipient
    let recipient_id = 2;
    let received_messages = message_system.get_messages_received_by_recipient(recipient_id);
    println!("Messages received by recipient {}: {:?}", recipient_id, received_messages);
}

