// Define the Product struct
struct Product {
    name: String,
    price: f64,
    quantity: i32,
}

impl Product {
    // Constructor method for Product
    fn new(name: String, price: f64, quantity: i32) -> Product {
        Product {
            name,
            price,
            quantity,
        }
    }

    // Method to update the price of the product
    fn update_price(&mut self, new_price: f64) {
        self.price = new_price;
    }

    // Method to update the quantity of the product
    fn update_quantity(&mut self, new_quantity: i32) {
        self.quantity = new_quantity;
    }
}

// Define the Inventory struct
struct Inventory {
    products: Vec<Product>,
}

impl Inventory {
    // Method to add a new product to the inventory
    fn add_product(&mut self, product: Product) {
        self.products.push(product);
    }

    // Method to calculate the total value of the inventory
    fn calculate_inventory_value(&self) -> f64 {
        let mut total_value = 0.0;
        for product in &self.products {
            total_value += product.price * product.quantity as f64;
        }
        total_value
    }
}

fn main() {
    // Create a new product and add it to the inventory
    let mut inventory = Inventory { products: vec![] };
    let new_product = Product::new(String::from("Example Product"), 10.0, 50);
    inventory.add_product(new_product);

    // Calculate the total value of the inventory
    let total_value = inventory.calculate_inventory_value();
    println!("Total inventory value: ${}", total_value);
}

