) -> Result<Waypoint, String> {
    // Retrieve the latest epoch change ledger info from the client
    let latest_epoch_change_li = client.latest_epoch_change_li().map_err(|e| format!("Error retrieving latest epoch change ledger info: {}", e))?;

    // Extract the epoch from the retrieved ledger info and compare it with the current epoch
    let epoch = latest_epoch_change_li.ledger_info().epoch();
    if epoch != curr_epoch {
        return Err(format!("Current epoch ({}) does not match the retrieved epoch ({})", curr_epoch, epoch));
    }

    // Create a waypoint for the epoch boundary using the retrieved ledger info
    let waypoint = Waypoint::new_epoch_boundary(latest_epoch_change_li.ledger_info())
        .map_err(|e| format!("Error creating waypoint for epoch boundary: {}", e))?;

    // Load the node configuration for a specific validator from the validator swarm
    let (node_config, _) = load_node_config(&env.validator_swarm, 3);
    // Assuming load_node_config returns a Result<(NodeConfig, _), String>

    Ok(waypoint)
}

