/// Represents a 4x4 matrix of bytes.
type Block = [[u8; 4]; 4];

/// Software-based implementation of the column mixing operation.
mod soft {
    pub fn mix_columns(block: &mut Block) {
        for i in 0..4 {
            let a = block[0][i];
            let b = block[1][i];
            let c = block[2][i];
            let d = block[3][i];

            block[0][i] = gmul(0x02, a) ^ gmul(0x03, b) ^ c ^ d;
            block[1][i] = a ^ gmul(0x02, b) ^ gmul(0x03, c) ^ d;
            block[2][i] = a ^ b ^ gmul(0x02, c) ^ gmul(0x03, d);
            block[3][i] = gmul(0x03, a) ^ b ^ c ^ gmul(0x02, d);
        }
    }

    /// Galois Field (256) multiplication.
    fn gmul(a: u8, b: u8) -> u8 {
        let mut p = 0;
        let mut counter = 0;
        let mut hi_bit_set: u8;
        while counter < 8 {
            if (b & 1) == 1 {
                p ^= a;
            }
            hi_bit_set = (a & 0x80) as u8;
            a <<= 1;
            if hi_bit_set == 0x80 {
                a ^= 0x1b;
            }
            b >>= 1;
            counter += 1;
        }
        p
    }
}

