use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, Expr, ItemFn};

#[proc_macro]
pub fn square_numbers(input: TokenStream) -> TokenStream {
    let input_fn: ItemFn = parse_macro_input!(input as ItemFn);

    let output = input_fn
        .block
        .stmts
        .iter()
        .map(|stmt| {
            if let syn::Stmt::Expr(expr) = stmt {
                if let Expr::Verbatim(_) = expr {
                    quote! { #expr }
                } else {
                    quote! { #expr * #expr }
                }
            } else {
                quote! { #stmt }
            }
        })
        .collect::<Vec<_>>();

    let output_fn = quote! {
        #input_fn
        #(#output)*
    };

    output_fn.into()
}

