fn is_valid_tree(edges: Vec<Vec<i32>>) -> bool {
    let mut parent = vec![0; edges.len() + 1];
    for i in 0..parent.len() {
        parent[i] = i as i32;
    }

    fn find(parent: &mut Vec<i32>, i: i32) -> i32 {
        if parent[i as usize] == i {
            return i;
        }
        parent[i as usize] = find(parent, parent[i as usize]);
        parent[i as usize]
    }

    fn union(parent: &mut Vec<i32>, x: i32, y: i32) {
        let x_set = find(parent, x);
        let y_set = find(parent, y);
        if x_set != y_set {
            parent[x_set as usize] = y_set;
        }
    }

    for edge in edges {
        let x = edge[0];
        let y = edge[1];
        let x_set = find(&mut parent, x);
        let y_set = find(&mut parent, y);
        if x_set == y_set {
            return false; // Cycle detected
        }
        union(&mut parent, x, y);
    }

    let mut count = 0;
    for i in 1..parent.len() {
        if parent[i] == i as i32 {
            count += 1;
        }
        if count > 1 {
            return false; // Multiple components detected
        }
    }

    true
}

fn main() {
    let edges = vec![
        vec![1, 4],
        vec![2, 3],
        vec![2, 4],
        vec![3, 4],
    ];
    println!("{}", is_valid_tree(edges)); // Output: true
}

