struct Slot<T> {
    value: Option<T>,
    // Other slot metadata if needed
}

struct Slab<T> {
    entries: Vec<Slot<T>>,
    len: usize,
    next: usize,
}

impl<T> Slab<T> {
    fn new(capacity: usize) -> Self {
        let mut entries = Vec::with_capacity(capacity);
        for _ in 0..capacity {
            entries.push(Slot { value: None });
        }
        Slab {
            entries,
            len: 0,
            next: 0,
        }
    }

    fn allocate(&mut self, value: T) -> Option<usize> {
        if self.len < self.entries.len() {
            let index = self.next;
            self.entries[index].value = Some(value);
            self.len += 1;
            self.next = self.find_next_available_slot();
            Some(index)
        } else {
            None
        }
    }

    fn deallocate(&mut self, index: usize) {
        if index < self.entries.len() {
            if self.entries[index].value.is_some() {
                self.entries[index].value = None;
                self.len -= 1;
                if index < self.next {
                    self.next = index;
                }
            }
        }
    }

    fn find_next_available_slot(&self) -> usize {
        for (index, slot) in self.entries.iter().enumerate().skip(self.next + 1) {
            if slot.value.is_none() {
                return index;
            }
        }
        self.entries.len()
    }
}

