enum ProtocolState {
    Init,
    Established,
    Closed,
}

macro_rules! assert_closed {
    ($x:expr) => {
        match $x {
            ProtocolState::Closed => {}
            state => panic!("State was {:?}, expected Closed", state),
        }
    };
}

macro_rules! assert_req_sent {
    ($x:expr) => {
        match $x {
            ProtocolState::Established => {}
            state => panic!("State was {:?}, expected Established", state),
        }
    };
}

fn main() {
    let mut state = ProtocolState::Init;

    // Transition from Init to Established
    match state {
        ProtocolState::Init => {
            state = ProtocolState::Established;
            assert_req_sent!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Established to Closed
    match state {
        ProtocolState::Established => {
            state = ProtocolState::Closed;
            assert_closed!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Closed to Init
    match state {
        ProtocolState::Closed => {
            state = ProtocolState::Init;
        }
        _ => panic!("Invalid state transition"),
    }
}

