use alloc::boxed::Box;
use core::ptr;

struct MemoryBlock {
    start: *mut u8,
    size: usize,
    next: Option<Box<MemoryBlock>>,
}

struct MemoryAllocator {
    memory: *mut u8,
    size: usize,
    free_list: Option<MemoryBlock>,
}

impl MemoryAllocator {
    fn init_allocator(size: usize) -> Self {
        let memory = unsafe { alloc::alloc::alloc(alloc::alloc::Layout::from_size_align(size, core::mem::align_of::<u8>())) as *mut u8 };
        MemoryAllocator {
            memory,
            size,
            free_list: Some(MemoryBlock {
                start: memory,
                size,
                next: None,
            }),
        }
    }

    fn allocate(&mut self, size: usize) -> Option<*mut u8> {
        let mut current = &mut self.free_list;
        while let Some(block) = current {
            if block.size >= size {
                let allocated_ptr = block.start;
                if block.size > size {
                    let remaining_block = MemoryBlock {
                        start: unsafe { block.start.add(size) },
                        size: block.size - size,
                        next: block.next.take(),
                    };
                    block.size = size;
                    block.next = Some(Box::new(remaining_block));
                } else {
                    *current = block.next.take();
                }
                return Some(allocated_ptr);
            }
            current = &mut block.next;
        }
        None
    }

    fn deallocate(&mut self, ptr: *mut u8, size: usize) {
        let mut current = &mut self.free_list;
        while let Some(block) = current {
            if ptr == block.start {
                let new_block = MemoryBlock {
                    start: ptr,
                    size,
                    next: block.next.take(),
                };
                *current = Some(Box::new(new_block));
                return;
            }
            current = &mut block.next;
        }
    }

    fn free_memory(&self) -> usize {
        let mut total_free = 0;
        let mut current = &self.free_list;
        while let Some(block) = current {
            total_free += block.size;
            current = &block.next;
        }
        total_free
    }
}

