fn parse_records(buf: &[u8], iso_size: u64) -> Result<Vec<Vec<u8>>, String> {
    let mut records = Vec::new();
    let mut offset_index = 0;

    loop {
        if offset_index + 8 > buf.len() {
            return Err("Invalid buffer length".to_string());
        }

        let offset = u64::from_le_bytes(buf[offset_index..offset_index + 8].try_into().unwrap());
        offset_index += 8;

        if offset == 0 {
            break;
        } else {
            if offset > iso_size {
                return Err(format!("Offset {} exceeds ISO size", offset));
            }

            if offset_index + 4 > buf.len() {
                return Err("Invalid buffer length".to_string());
            }

            let length = u32::from_le_bytes(buf[offset_index..offset_index + 4].try_into().unwrap()) as usize;
            offset_index += 4;

            if offset_index + length > buf.len() {
                return Err("Invalid buffer length".to_string());
            }

            let payload = buf[offset_index..offset_index + length].to_vec();
            records.push(payload);
            offset_index += length;
        }
    }

    Ok(records)
}

