function limitRate(obj, methodName, limit, duration) {
  const fn = obj[methodName];
  const ratesPropName = `_methodRates__${methodName}`;

  if (!obj[ratesPropName]) {
    obj[ratesPropName] = {
      count: 0,
      lastReset: Date.now()
    };
  }

  const rateObj = obj[ratesPropName];

  return function () {
    const now = Date.now();
    if (now - rateObj.lastReset > duration) {
      rateObj.count = 0;
      rateObj.lastReset = now;
    }

    if (rateObj.count < limit) {
      rateObj.count++;
      return fn.apply(obj, arguments);
    } else {
      throw new Error(`Rate limit exceeded for method ${methodName}`);
    }
  };
}
```

