mod job_management {
    use std::collections::HashMap;

    pub struct Job {
        id: u64,
        details: String,
    }

    pub struct JobManager {
        jobs: HashMap<u64, Job>,
        next_id: u64,
    }

    impl JobManager {
        pub fn new() -> JobManager {
            JobManager {
                jobs: HashMap::new(),
                next_id: 1,
            }
        }

        pub fn create_job(&mut self, details: String) -> u64 {
            let id = self.next_id;
            self.jobs.insert(id, Job { id, details });
            self.next_id += 1;
            id
        }

        pub fn cancel_job(&mut self, id: u64) -> Result<(), String> {
            if self.jobs.contains_key(&id) {
                self.jobs.remove(&id);
                Ok(())
            } else {
                Err("Job not found".to_string())
            }
        }

        pub fn delete_job(&mut self, id: u64) -> Result<(), String> {
            if self.jobs.contains_key(&id) {
                self.jobs.remove(&id);
                Ok(())
            } else {
                Err("Job not found".to_string())
            }
        }

        pub fn get_all_jobs(&self) -> Vec<&Job> {
            self.jobs.values().collect()
        }
    }
}

