use std::convert::TryFrom;

#[derive(Debug, PartialEq)]
enum Transport {
    Tcp,
    Udp,
    Tls,
}

struct SrvDomain {
    protocol: Transport,
    domain: String,
    secure: bool,
}

impl SrvDomain {
    fn transport(&self) -> Transport {
        match (self.protocol, self.secure) {
            (Transport::Tcp, false) => Transport::Tcp,
            (Transport::Tcp, true) => Transport::Tls,
            (Transport::Udp, _) => Transport::Udp,
        }
    }
}

impl TryFrom<String> for SrvDomain {
    type Error = &'static str;

    fn try_from(value: String) -> Result<Self, Self::Error> {
        let parts: Vec<&str> = value.split('.').collect();
        if parts.len() < 4 {
            return Err("Invalid format");
        }
        let protocol = match (parts[1], parts[2]) {
            ("_tcp", "sips") => Transport::Tcp,
            ("_udp", "sip") => Transport::Udp,
            _ => return Err("Invalid format"),
        };
        let domain = parts[3..].join(".");
        let secure = parts[1] == "_sips";
        Ok(SrvDomain {
            protocol,
            domain,
            secure,
        })
    }
}

fn main() {
    let srv_domain_str = "_sips._tcp.example.com";
    let srv_domain = SrvDomain::try_from(srv_domain_str.clone()).unwrap();
    assert_eq!(srv_domain.secure, true);
    assert_eq!(srv_domain.protocol, Transport::Tcp);
    assert_eq!(srv_domain.domain, "example.com");
    assert_eq!(srv_domain.transport(), Transport::Tls);
    assert_eq!(srv_domain.to_string(), srv_domain_str);
}

