fn play_game(grid: &mut Vec<Vec<char>>, moves: &str) -> String {
    let mut player_pos = (0, 0);
    for (i, row) in grid.iter().enumerate() {
        if let Some(j) = row.iter().position(|&c| c == 'X') {
            player_pos = (i, j);
            break;
        }
    }

    for ch in moves.chars() {
        let (dx, dy) = match ch {
            'U' => (-1, 0),
            'D' => (1, 0),
            'L' => (0, -1),
            'R' => (0, 1),
            _ => (0, 0),
        };

        let (x, y) = player_pos;
        let new_x = x as i32 + dx;
        let new_y = y as i32 + dy;

        if new_x >= 0 && new_x < grid.len() as i32 && new_y >= 0 && new_y < grid[0].len() as i32 {
            let new_x = new_x as usize;
            let new_y = new_y as usize;
            if grid[new_x][new_y] != '#' {
                if grid[new_x][new_y] == 'O' {
                    grid[new_x][new_y] = '.';
                }
                grid[x][y] = '.';
                grid[new_x][new_y] = 'X';
                player_pos = (new_x, new_y);
            }
        }
    }

    grid.iter()
        .map(|row| row.iter().collect::<String>())
        .collect::<Vec<String>>()
        .join("\n")
}

