fn curvature(x: f64) -> f64 {
    // Define the curve function here, for example:
    // let f = |x: f64| x.powi(2) + 3.0 * x + 2.0;

    // Calculate the first derivative of the curve function at point x
    let h = 1e-10; // Small value for numerical differentiation
    let df_dx = (f(x + h) - f(x - h)) / (2.0 * h);

    // Calculate the second derivative of the curve function at point x
    let d2f_dx2 = (f(x + h) - 2.0 * f(x) + f(x - h)) / (h.powi(2));

    // Calculate the curvature using the formula
    let curvature = d2f_dx2.abs() / (1.0 + df_dx.powi(2)).powf(3.0 / 2.0);

    curvature
}

