use io::FilteredNodes;

pub fn filter_nodes(fbas: &Fbas, threshold: usize) -> FilteredNodes {
    let mut valid_nodes = NodeIdSet::new();
    let mut invalid_nodes = NodeIdSet::new();

    for (node_id, quorum_set) in fbas.iter() {
        if quorum_set.len() >= threshold {
            valid_nodes.extend(quorum_set.iter());
        } else {
            invalid_nodes.extend(quorum_set.iter());
        }
    }

    FilteredNodes {
        valid_nodes,
        invalid_nodes,
    }
}

