}

// Define the FP MMX value structure
struct FpMmxValue {
    Reg128: WHV_UINT128,
}

// Define the FP MMX register index enum
enum WinFpRegIndex {
    FpMmx0,
    // ... (other FP MMX register indices)
}

// Define the constant for the number of FP MMX registers
const NUM_FPMMX_REGS: usize = 8;
const NUM_FPMMX_REGS_TOTAL: usize = NUM_FPMMX_REGS * 16; // Total size in bytes for all FP MMX registers

// Implement the conversion function
fn convert_fp_mmx_registers(from: &SourceStruct, fpu_state: &mut DestinationStruct) -> DestinationStruct {
    for idx in 0..NUM_FPMMX_REGS {
        let from_idx = WinFpRegIndex::FpMmx0 as usize + idx;
        unsafe {
            // Extract the values from the source structure and store them in the FPU state of the destination structure
            fpu_state.fpr[(idx * 16)..((idx + 1) * 16)].copy_from_slice(&WHV_UINT128::to_u8_array(&from.values[from_idx].Reg128));
        }
    }
    fpu_state.clone() // Return the updated fpu_state
}

