use core::ecs::{life_cycle::EntityChanges, Comp, Entity, Universe, WorldRef};
use std::collections::HashMap;

struct SimpleECS {
    entities: HashMap<Entity, HashMap<String, Box<dyn Comp>>>,
}

impl SimpleECS {
    fn new() -> SimpleECS {
        SimpleECS {
            entities: HashMap::new(),
        }
    }

    fn create_entity(&mut self) -> Entity {
        let entity = Universe::new().create_entity();
        self.entities.insert(entity, HashMap::new());
        entity
    }

    fn add_component<T: 'static + Comp>(&mut self, entity: Entity, component_name: &str, component: T) {
        if let Some(components) = self.entities.get_mut(&entity) {
            components.insert(component_name.to_string(), Box::new(component));
        }
    }

    fn remove_component(&mut self, entity: Entity, component_name: &str) {
        if let Some(components) = self.entities.get_mut(&entity) {
            components.remove(component_name);
        }
    }

    fn get_component<T: 'static + Comp>(&self, entity: Entity, component_name: &str) -> Option<&T> {
        if let Some(components) = self.entities.get(&entity) {
            if let Some(component) = components.get(component_name) {
                if let Some(component) = component.downcast_ref::<T>() {
                    return Some(component);
                }
            }
        }
        None
    }
}

