pub fn parseBadges(html: &str) -> Option<(String, u32)> {
    let img_regex = Regex::new(r#"<img src="https://img.shields.io/crates/v/([^"]+).svg\?style=flat-square".*?/>"#).unwrap();
    let a_regex = Regex::new(r#"<a href="https://crates.io/crates/([^"]+)">.*?<img src="https://img.shields.io/crates/d/([^"]+).svg\?style=flat-square".*?/>"#).unwrap();

    if let Some(captures) = img_regex.captures(html) {
        let version = captures.get(1).unwrap().as_str().to_string();
        if let Some(a_captures) = a_regex.captures(html) {
            let downloads = a_captures.get(2).unwrap().as_str().parse::<u32>().unwrap_or(0);
            return Some((version, downloads));
        }
    }
    None
}

