use std::collections::HashMap;

pub struct Graph {
    vertices: HashMap<u32, Vec<u32>>,
}

impl Graph {
    pub fn new() -> Self {
        Graph {
            vertices: HashMap::new(),
        }
    }

    pub fn add_vertex(&mut self, vertex: u32) {
        self.vertices.entry(vertex).or_insert(Vec::new());
    }

    pub fn add_edge(&mut self, from: u32, to: u32) {
        self.vertices.entry(from).or_insert(Vec::new()).push(to);
        // For undirected graph, add the reverse edge as well
        self.vertices.entry(to).or_insert(Vec::new()).push(from);
    }

    pub fn has_vertex(&self, vertex: u32) -> bool {
        self.vertices.contains_key(&vertex)
    }

    pub fn has_edge(&self, from: u32, to: u32) -> bool {
        if let Some(adj_list) = self.vertices.get(&from) {
            adj_list.contains(&to)
        } else {
            false
        }
    }
}

fn main() {
    let mut graph = Graph::new();
    graph.add_vertex(1);
    graph.add_vertex(2);
    graph.add_edge(1, 2);

    println!("Graph has vertex 1: {}", graph.has_vertex(1)); // Output: true
    println!("Graph has edge 1 -> 2: {}", graph.has_edge(1, 2)); // Output: true
    println!("Graph has edge 2 -> 1: {}", graph.has_edge(2, 1)); // Output: true (for undirected graph)
}

