fn to_amino_bytes(num: i64) -> Vec<u8> {
    if num >= 0 {
        num.to_le_bytes().to_vec()
    } else {
        let abs_num = num.abs() as u64;
        let mut bytes = abs_num.to_le_bytes().to_vec();
        bytes[7] |= 0x80; // Set the most significant bit of the last byte to 1
        bytes
    }
}

fn main() {
    let num = -1000000000000000000;
    assert_eq!(b"-1000000000000000000", to_amino_bytes(num).as_slice());
}

