use futures::prelude::*;

struct CustomFilter<S, F> {
    inner: S,
    filter: F,
}

impl<S, F> Stream for CustomFilter<S, F>
where
    S: Stream,
    F: FnMut(&S::Item) -> bool,
{
    type Item = S::Item;
    type Error = S::Error;

    fn poll(&mut self) -> Poll<Self::Item, Self::Error> {
        loop {
            match self.inner.poll() {
                Ok(Async::Ready(inner_item)) => {
                    if (self.filter)(&inner_item) {
                        return Ok(Async::Ready(inner_item));
                    }
                }
                Ok(Async::NotReady) => return Ok(Async::NotReady),
                Err(e) => return Err(e),
            }
        }
    }
}

