use inkwell::context::Context;
use inkwell::execution_engine::JitFunction;
use inkwell::module::Module;
use std::fs;

fn analyze_and_execute_jit(file_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let context = Context::create();
    let module = context.create_module("main_module");

    let source_code = fs::read_to_string(file_path)?;

    let main_function_exists = source_code.contains("fn main()");
    if main_function_exists {
        let execution_engine = module.create_jit_execution_engine(inkwell::OptimizationLevel::None)?;

        let function = module.add_function("main", context.i32_type().fn_type(&[], false), None);
        let basic_block = context.append_basic_block(function, "entry");
        let builder = context.create_builder();
        builder.position_at_end(basic_block);

        let i32_type = context.i32_type();
        let exit_code = i32_type.const_int(0, false);
        builder.build_return(Some(&exit_code));

        let jit_function = JitFunction::new(&function, &execution_engine)?;

        let res = jit_function.call();
        println!("Exit code: {}", res);
        Ok(())
