fn truncate_to_char_boundary(s: &str, max_bytes: usize) -> &str {
    if max_bytes >= s.len() {
        return s;
    }

    let mut truncated = &s[..max_bytes];
    while !truncated.is_char_boundary(truncated.len()) {
        truncated = &truncated[..truncated.len() - 1];
    }
    truncated
}

