fn calculate_checksum(strings: &[String]) -> usize {
    let mut two_duplicates = 0;
    let mut three_duplicates = 0;

    for s in strings {
        let mut counts = [0; 26];
        for c in s.chars() {
            let index = (c as u8 - b'a') as usize;
            counts[index] += 1;
        }

        if counts.iter().any(|&count| count == 2) {
            two_duplicates += 1;
        }
        if counts.iter().any(|&count| count == 3) {
            three_duplicates += 1;
        }
    }

    two_duplicates * three_duplicates
}

fn main() {
    let strings = vec!["hello".to_string(), "world".to_string(), "apple".to_string(), "banana".to_string(), "orange".to_string()];
    println!("Checksum: {}", calculate_checksum(&strings));
}

