use std::mem;

struct Maybe<T> {
    data: mem::MaybeUninit<T>,
    initialized: bool,
}

impl<T> Maybe<T> {
    fn new() -> Self {
        Maybe {
            data: mem::MaybeUninit::uninit(),
            initialized: false,
        }
    }

    fn initialize(&mut self, value: T) {
        if self.initialized {
            panic!("Already initialized");
        }
        unsafe {
            self.data.as_mut_ptr().write(value);
        }
        self.initialized = true;
    }

    fn get(&self) -> &T {
        if !self.initialized {
            panic!("Not initialized");
        }
        unsafe { &*self.data.as_ptr() }
    }
}

impl<T> Drop for Maybe<T> {
    fn drop(&mut self) {
        if self.initialized {
            unsafe {
                self.data.as_mut_ptr().drop_in_place();
            }
        }
    }
}

fn main() {
    let mut maybe_int = Maybe::new();
    maybe_int.initialize(42);
    println!("Initialized value: {}", maybe_int.get());
}

