}

impl Library {
    // Constructor method to create a new library
    fn new() -> Library {
        Library { books: Vec::new() }
    }

    // Method to add a new book to the library
    fn add_book(&mut self, title: String, author: String, isbn: u32) {
        let new_book = Book {
            title: title,
            author: author,
            isbn: isbn,
        };
        self.books.push(new_book);
    }

    // Method to remove a book from the library based on its ISBN
    fn remove_book(&mut self, isbn: u32) {
        self.books.retain(|book| book.isbn != isbn);
    }

    // Method to search for a book in the library based on its title
    fn search_book(&self, title: &str) -> Option<&Book> {
        self.books.iter().find(|&book| book.title == title)
