use ptx::cuda;

pub fn sum_array_with_cuda(input: &[i32]) -> i32 {
    // Allocate device memory for input array
    let device_input = cuda::allocate_device_memory(input.len() * std::mem::size_of::<i32>());

    // Copy input array to device memory
    cuda::copy_to_device(device_input, input);

    // Launch CUDA kernel to calculate sum
    let block_size = 256;
    let grid_size = (input.len() + block_size - 1) / block_size;
    let sum = cuda::launch_sum_kernel(device_input, input.len(), block_size, grid_size);

    // Free device memory
    cuda::free_device_memory(device_input);

    sum
}

