    // Generate an absolute character offset within a specified maximum length
    let offset_strategy = arb_absolute_char_offset(100);
    let offset = offset_strategy.prop_map(|offset| offset.to_usize());
    println!("Generated absolute character offset: {}", offset);

    // Generate a rope and an absolute character offset within that rope
    let rope_and_offset_strategy = arb_rope_and_offset();
    let (rope, offset) = rope_and_offset_strategy.prop_map(|(rope, offset)| (rope.to_string(), offset.to_usize()));
    println!("Generated rope: {}", rope);
    println!("Generated absolute character offset within the rope: {}", offset);
}

