use std::collections::HashMap;
use criterion::{black_box, criterion_group, criterion_main, Criterion};

struct CacheString {
    cache: HashMap<String, String>,
}

impl CacheString {
    fn from_str_truncate(s: &str) -> String {
        // Truncate the string to a maximum length if necessary
        let truncated_string = if s.len() > 10 {
            String::from(&s[..10])
        } else {
            String::from(s)
        };
        truncated_string
    }

    fn get(&self, key: &str) -> Option<&String> {
        self.cache.get(key)
    }
}

fn cache_from_str_truncate_benchmark(c: &mut Criterion) {
    let string = "iiiijjjjkkkkllllmmmmn";
    c.bench_function("cache from_str_truncate", |b| {
        b.iter(|| CacheString::from_str_truncate(black_box(string)))
    });
}

fn main() {
    let mut cache = CacheString {
        cache: HashMap::new(),
    };

    let key = "example_key";
    let value = "example_value";

    // Store a string in the cache
    cache.cache.insert(String::from(key), String::from(value));

    // Retrieve the stored string from the cache
    if let Some(stored_value) = cache.get(key) {
        println!("Retrieved value from cache: {}", stored_value);
    } else {
        println!("Value not found in cache");
    }

    criterion_group!(benches, cache_from_str_truncate_benchmark);
    criterion_main!(benches);
}

