use std::pin::Pin;
use std::task::{Context, Poll};
use futures::stream::Stream;

struct CustomStream {
    // Fields and state for the custom stream
    sequence: Vec<i32>,
    current_index: usize,
}

impl Stream for CustomStream {
    type Item = i32;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        // Check if there are more elements in the sequence
        if self.current_index < self.sequence.len() {
            let next_value = self.sequence[self.current_index];
            self.current_index += 1;
            Poll::Ready(Some(next_value))
        } else {
            // No more elements in the sequence
            Poll::Ready(None)
        }
    }
}

fn main() {
    // Example usage of the CustomStream
    let sequence = vec![1, 2, 3, 4, 5];
    let custom_stream = CustomStream {
        sequence,
        current_index: 0,
    };

    // Poll for values from the custom stream
    let mut stream_pin = Pin::new(&mut custom_stream);
    let mut cx = Context::from_waker(futures::task::noop_waker_ref());
    while let Poll::Ready(Some(value)) = custom_stream.poll_next(&mut cx) {
        println!("Received value: {}", value);
    }
}

