    async fn init_tso_limit(&self) -> usize {
        // Acquire a lock to ensure exclusive access to the initialization process
        let mut initialized = self.tso_limit_initialized.lock().unwrap();

        // Check if the limit has been initialized before
        if !*initialized {
            // Initialize the Thread Synchronization Object limit to a default value
