pub fn calculate_smoke_dispersion(
    basin_dimensions: (f64, f64, f64), 
    initial_positions: Vec<(f64, f64, f64)>, 
    initial_velocities: Vec<(f64, f64, f64)>, 
    time_interval: f64
) -> Vec<(f64, f64, f64)> {
    let mut final_positions = Vec::new();

    for i in 0..initial_positions.len() {
        let (x, y, z) = initial_positions[i];
        let (vx, vy, vz) = initial_velocities[i];

        let final_x = x + vx * time_interval;
        let final_y = y + vy * time_interval;
        let final_z = z + vz * time_interval;

        final_positions.push((final_x, final_y, final_z));
    }

    final_positions
}

