        for (tid, status) in waiters.iter_mut() {
            if *tid != me {
                *status = CondvarWaitStatus::Broadcast(current::clock());
                // Note: the task might have been unblocked by a previous signal
                ExecutionState::with(|s| s.get_mut(*tid).unblock());
            }
        }
    }
}

