    data: T,
    clone_count: usize,
    drop_count: usize,
}

impl<T> CustomPointer<T> {
    fn new(data: T) -> Self {
        CustomPointer {
            data,
            clone_count: 0,
            drop_count: 0,
        }
    }
}

impl<T> Deref for CustomPointer<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        &self.data
    }
}

impl<T> Drop for CustomPointer<T> {
    fn drop(&mut self) {
        self.drop_count += 1;
    }
}

fn main() {
    let value = 42;
    let custom_ptr = CustomPointer::new(value);
    let _clone1 = custom_ptr.clone();
    let _clone2 = custom_ptr.clone();
    drop(custom_ptr);
    // At this point, the drop_count for custom_ptr should be 1
}

