pub struct ListQueue<T> {
    elements: Vec<T>,
}

impl<T> ListQueue<T> {
    pub fn new() -> Self {
        ListQueue { elements: Vec::new() }
    }

    pub fn enqueue(&mut self, element: T) {
        self.elements.push(element);
    }

    pub fn dequeue(&mut self) -> Option<T> {
        if self.is_empty() {
            None
        } else {
            Some(self.elements.remove(0))
        }
    }

    pub fn peek(&self) -> Option<&T> {
        self.elements.first()
    }

    pub fn is_empty(&self) -> bool {
        self.elements.is_empty()
    }
}

fn main() {
    let mut queue: ListQueue<i32> = ListQueue::new();
    queue.enqueue(5);
    queue.enqueue(10);
    println!("{:?}", queue.peek()); // Output: Some(&5)
    println!("{:?}", queue.dequeue()); // Output: Some(5)
    println!("{:?}", queue.dequeue()); // Output: Some(10)
    println!("{:?}", queue.dequeue()); // Output: None
    println!("{:?}", queue.is_empty()); // Output: true
}

