fn recursive_select<F, CS>(
    index_bits_be: &[Scalar<F>],
    array: &[Scalar<F>],
) -> Result<Scalar<F>, Box<dyn Error>>
where
    F: Field,
    CS: ConstraintSystem<F>,
{
    assert!(!array.is_empty(), "internal error in recursive_select 1");

    if array.len() == 1 {
        return Ok(array[0].clone());
    }

    let index = index_bits_be[0]; // Select the first index from index_bits_be
    let remaining_indices = &index_bits_be[1..]; // Get the remaining indices

    let selected_element = &array[index.into_u64() as usize]; // Use the selected index to access the array

    recursive_select(remaining_indices, selected_element) // Recur with the remaining indices and the selected element
}

