pub fn run_command(mut command: String) -> String {
    let mut items: Vec<String> = Vec::new();

    if !command.is_empty() {
        let parts: Vec<&str> = command.splitn(2, ' ').collect();
        match parts[0] {
            ":add" => {
                if parts.len() > 1 {
                    items.push(parts[1].to_string());
                    return "Item added successfully".to_string();
                } else {
                    return "Invalid command".to_string();
                }
            }
            ":remove" => {
                if parts.len() > 1 {
                    if let Some(index) = items.iter().position(|item| *item == parts[1]) {
                        items.remove(index);
                        return "Item removed successfully".to_string();
                    } else {
                        return "Item not found".to_string();
                    }
                } else {
                    return "Invalid command".to_string();
                }
            }
            ":list" => {
                if items.is_empty() {
                    return "No items in the list".to_string();
                } else {
                    let list_str = items.join(", ");
                    return list_str;
                }
            }
            _ => return "Invalid command".to_string(),
        }
    } else {
        return "Invalid command".to_string();
    }
}

