fn valid_nick(nickname: &str) -> bool {
    if nickname.len() < 6 {
        return false;
    }
    if !nickname.chars().next().map_or(false, |c| c.is_ascii_alphabetic() && c.is_ascii_uppercase()) {
        return false;
    }
    if !nickname.chars().all(|c| c.is_ascii_alphanumeric()) {
        return false;
    }
    true
}

