use std::collections::HashMap;

// Define the Value and Scope types
enum Value {
    Bool(bool),
    // Add other value types as needed
}

struct Scope {
    // Define the scope structure
    name: String,
    values: HashMap<String, Value>,
}

impl Scope {
    fn new(name: &str) -> Scope {
        Scope {
            name: name.to_string(),
            values: HashMap::new(),
        }
    }

    fn declare(&mut self, name: &str, value: Value) -> Result<(), String> {
        if self.values.contains_key(name) {
            Err(format!("Value '{}' already exists in scope '{}'", name, self.name))
        } else {
            self.values.insert(name.to_string(), value);
            Ok(())
        }
    }
}

impl Clone for Scope {
    fn clone(&self) -> Scope {
        let mut cloned_scope = Scope::new(&self.name);
        for (key, value) in &self.values {
            cloned_scope.values.insert(key.clone(), value.clone());
        }
        cloned_scope
    }
}

struct Environment {
    // Define the environment structure
    scopes: Vec<Scope>,
}

impl Environment {
    fn new() -> Environment {
        Environment { scopes: vec![] }
    }

    fn declare(&mut self, name: &str, value: Value) -> Result<(), String> {
        if let Some(current_scope) = self.scopes.last_mut() {
            current_scope.declare(name, value)
        } else {
            Err("No scope available to declare the value".to_string())
        }
    }
}

impl Scope {
    fn create_lazy_namespace<F>(&mut self, name: &str, initializer: F) -> Result<Scope, String>
    where
        F: FnOnce(&mut Environment) -> Result<(), String>,
    {
        let mut lazy_scope = Scope::new(name);
        let mut env = Environment::new();
        env.scopes.push(lazy_scope.clone());

        match initializer(&mut env) {
            Ok(()) => {
                self.values.insert(name.to_string(), Value::Scope(lazy_scope.clone()));
                Ok(lazy_scope)
            }
            Err(err) => Err(err),
        }
    }

    fn r#use(&mut self, lazy_scope: &Scope) {
        for (key, value) in &lazy_scope.values {
            self.values.insert(key.clone(), value.clone());
        }
    }
}

