/// Represents a borrowed string slice with a specific lifetime.
struct Kstr<'a> {
    inner: &'a str,
}

impl<'a> Kstr<'a> {
    /// Creates a new `Kstr` instance from a borrowed string slice.
    fn borrowed(inner: &'a str) -> Self {
        Kstr { inner }
    }

    /// Converts the borrowed string slice into an owned string with a `'static` lifetime.
    fn into_owned(self) -> Kstr<'static> {
        Kstr::owned(self.inner.to_owned())
    }

    /// Creates a new `Kstr` instance from an owned string with a `'static` lifetime.
    fn owned(inner: String) -> Kstr<'static> {
        Kstr { inner: Box::leak(inner.into_boxed_str()) }
    }
}

impl<'a> Deref for Kstr<'a> {
    type Target = str;

    /// Allows the `Kstr` instance to be dereferenced to a string slice.
    fn deref(&self) -> &str {
        self.inner
    }
}

