use serde_json::{Value, from_str};
use chrono::{DateTime, Utc, NaiveTime, Timelike};

#[derive(Debug, Deserialize)]
struct ExitStatus {
    exitTime: String,
    statusCode: i32,
}

pub fn calculate_average_exit_time(data: &str) -> Option<String> {
    let statuses: Vec<ExitStatus> = match from_str(data) {
        Ok(val) => val,
        Err(_) => return None,
    };

    let non_zero_statuses: Vec<&ExitStatus> = statuses.iter().filter(|s| s.statusCode != 0).collect();
    if non_zero_statuses.is_empty() {
        return None;
    }

    let total_exit_time: NaiveTime = non_zero_statuses.iter()
        .map(|s| DateTime::parse_from_rfc3339(&s.exitTime).unwrap().naive_utc().time())
        .fold(NaiveTime::from_hms(0, 0, 0), |acc, t| acc + t);

    let average_exit_time = total_exit_time / non_zero_statuses.len() as u32;
    Some(format!("{:02}:{:02}:{:02}", average_exit_time.hour(), average_exit_time.minute(), average_exit_time.second()))
}

