use arduino_uno::Peripherals;
use core::time::Duration;

struct Task {
    task_fn: fn(),
    interval: Duration,
    last_executed: core::time::Instant,
}

pub struct TaskScheduler {
    tasks: Vec<Task>,
}

impl TaskScheduler {
    pub fn new() -> TaskScheduler {
        TaskScheduler { tasks: Vec::new() }
    }

    pub fn schedule_task(&mut self, task_fn: fn(), interval: Duration) {
        let task = Task {
            task_fn,
            interval,
            last_executed: core::time::Instant::now(),
        };
        self.tasks.push(task);
    }

    pub fn run(&mut self, peripherals: Peripherals) {
        loop {
            for task in &mut self.tasks {
                if task.last_executed.elapsed() >= task.interval {
                    task.task_fn();
                    task.last_executed = core::time::Instant::now();
                }
            }
            // Add non-blocking delay to prevent busy-waiting
            peripherals.delay_ms(1);
        }
    }
}

#[arduino_uno::entry]
fn main() -> ! {
    let peripherals = arduino_uno::Peripherals::take().unwrap();
    let mut scheduler = TaskScheduler::new();

    // Example: Schedule a task to blink an LED every 500ms
    scheduler.schedule_task(|| {
        peripherals.digital.write(13, arduino_uno::hal::digital::State::High);
        peripherals.delay_ms(100);
        peripherals.digital.write(13, arduino_uno::hal::digital::State::Low);
    }, core::time::Duration::from_millis(500));

    scheduler.run(peripherals);
}

