fn count_valid_passwords(passwords: &[&str]) -> usize {
    let mut valid_count = 0;
    for entry in passwords {
        let parts: Vec<&str> = entry.split(|c| c == '-' || c == ' ' || c == ':').collect();
        let min = parts[0].parse::<usize>().unwrap();
        let max = parts[1].parse::<usize>().unwrap();
        let target_char = parts[2].chars().next().unwrap();
        let password = parts[4];

        let count = password.chars().filter(|&c| c == target_char).count();
        if count >= min && count <= max {
            valid_count += 1;
        }
    }
    valid_count
}

fn main() {
    let passwords = [
        "1-3 a: abcde",
        "1-3 b: cdefg",
        "2-9 c: ccccccccc",
    ];
    let result = count_valid_passwords(&passwords);
    println!("Total valid passwords: {}", result);
}

