use tokio::time::{Duration, sleep};
use tokio::sync::mpsc;

enum Message {
    Ping,
    Pong,
}

async fn sender(mut tx: mpsc::Sender<Message>) {
    loop {
        // Send a ping message every 10 seconds
        if let Err(_) = tx.send(Message::Ping).await {
            break;
        }
        sleep(Duration::from_secs(10)).await;
    }
}

async fn receiver(mut rx: mpsc::Receiver<Message>) {
    loop {
        match rx.recv().await {
            Some(message) => {
                match message {
                    Message::Ping => {
                        // Respond with a pong message
                        if let Err(_) = rx.send(Message::Pong).await {
                            break;
                        }
                    }
                    _ => {}
                }
            }
            None => break,
        }
    }
}

#[tokio::main]
async fn main() {
    let (tx, mut rx) = mpsc::channel(10);

    // Spawn sender and receiver tasks
    tokio::spawn(async move {
        sender(tx).await;
    });

    tokio::spawn(async move {
        receiver(rx).await;
    });

    // Prevent main task from completing immediately
    loop {
        sleep(Duration::from_secs(1)).await;
    }
}

