        if separators.contains(&c) {
            modified_string.push(c);
        } else if let Some(index) = alphabet.iter().position(|&x| x == c) {
            modified_string.push(alphabet[index]);
        } else {
            modified_string.push(c);
        }
    }
    modified_string
}

