macro_rules! retry_until_ok {
    ($id:expr, { $($f:tt)* }) => {
        {
            let mut delay = std::time::Duration::from_millis(100); // Initial delay
            loop {
                match { $($f)* } {
                    Ok(result) => break result,
                    Err(_) => {
                        std::thread::sleep(delay);
                        // Increase the delay exponentially for the next retry
                        delay = delay.mul_f32(1.5).min(std::time::Duration::from_secs(60)); // Maximum delay of 1 minute
                    }
                }
            }
        }
    };
}

