use std::collections::{HashMap, VecDeque};

fn evict_least_recently_used(cache: &mut HashMap<String, String>, max_capacity: usize, name: &str) {
    if cache.len() >= max_capacity {
        let mut access_order: VecDeque<&String> = VecDeque::new();
        for key in cache.keys() {
            access_order.push_back(key);
        }

        if let Some(key_to_evict) = access_order.pop_front() {
            cache.remove(key_to_evict);
        }
    }
}

