use std::collections::BTreeMap;

struct KeyValueStore {
    store: BTreeMap<i32, i32>,
}

impl KeyValueStore {
    fn new() -> Self {
        KeyValueStore {
            store: BTreeMap::new(),
        }
    }

    fn insert(&mut self, key: i32, value: i32) {
        self.store.insert(key, value);
    }

    fn get(&self, key: i32) -> Option<&i32> {
        self.store.get(&key)
    }

    fn delete(&mut self, key: i32) {
        self.store.remove(&key);
    }

    fn find_next(&self, key: i32) -> Option<(&i32, &i32)> {
        if let Some(entry) = self.store.range(key..).next() {
            Some(entry)
        } else {
            None
        }
    }
}

fn main() {
    let mut kv_store = KeyValueStore::new();
    kv_store.insert(3, 30);
    kv_store.insert(1, 10);
    kv_store.insert(5, 50);

    println!("{:?}", kv_store.get(3)); // Output: Some(30)
    println!("{:?}", kv_store.get(2)); // Output: None

    kv_store.delete(1);
    println!("{:?}", kv_store.get(1)); // Output: None

    println!("{:?}", kv_store.find_next(3)); // Output: Some((&3, &30))
    println!("{:?}", kv_store.find_next(4)); // Output: Some((&5, &50))
    println!("{:?}", kv_store.find_next(6)); // Output: None
}

