use std::sync::{Arc, Mutex};
use std::thread;

impl BatchRequest {
    pub fn process(&self) -> Vec<Result<Response, Error>> {
        let results: Arc<Mutex<Vec<Result<Response, Error>>>> = Arc::new(Mutex::new(Vec::new()));

        let mut handles = vec![];

        for request in &self.requests {
            let results_clone = Arc::clone(&results);
            let request_clone = request.clone();
            let preparer_clone = self.preparer.clone();

            let handle = thread::spawn(move || {
                let result = preparer_clone.prepare_and_send(&request_clone);
                results_clone.lock().unwrap().push(result);
            });

            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        Arc::try_unwrap(results)
            .unwrap()
            .into_inner()
            .unwrap()
    }
}

