use std::collections::HashMap;

struct EnumInfo {
    variants: Vec<String>,
    associated_data: HashMap<String, Vec<String>>,
}

fn resolve_enum_def(enum_definition: &str) -> EnumInfo {
    let mut variants = Vec::new();
    let mut associated_data = HashMap::new();

    let lines: Vec<&str> = enum_definition.lines().map(|line| line.trim()).collect();

    for line in lines {
        if line.starts_with("enum") {
            continue;
        }
        if line.starts_with("}") {
            break;
        }
        let variant_parts: Vec<&str> = line.split('(').collect();
        let variant_name = variant_parts[0].trim();
        variants.push(variant_name.to_string());

        if variant_parts.len() > 1 {
            let data_types: Vec<String> = variant_parts[1]
                .trim_end_matches(')')
                .split(',')
                .map(|s| s.trim().to_string())
                .collect();
            associated_data.insert(variant_name.to_string(), data_types);
        }
    }

    EnumInfo {
        variants,
        associated_data,
    }
}

fn main() {
    let enum_definition = r#"
        enum MyEnum {
            Variant1,
            Variant2(i32),
            Variant3(String, bool),
        }
    "#;

    let enum_info = resolve_enum_def(enum_definition);
    println!("Enum Variants: {:?}", enum_info.variants);
    for (variant, data_types) in enum_info.associated_data.iter() {
        println!("Variant: {} - Associated Data Types: {:?}", variant, data_types);
    }
}

