impl<K: Ord + Hash + Clone, V: Clone> HeapHashMap<K, V> {
    fn insert(&mut self, key: K, value: V) {
        self.heap.push((key.clone(), value.clone()));
        self.map.insert(key, value);
    }

    fn remove(&mut self, key: &K) {
        if let Some(value) = self.map.remove(key) {
            self.heap.retain(|(k, _)| k != key);
        }
    }

    fn get_min(&self) -> Option<(&K, &V)> {
        self.heap.peek().and_then(|(k, v)| self.map.get(k).map(|val| (k, val)))
    }

    fn get_max(&self) -> Option<(&K, &V)> {
        self.heap.iter().max().and_then(|(k, _)| self.map.get(k).map(|val| (k, val)))
    }

    fn is_empty(&self) -> bool {
        self.heap.is_empty()
    }
}

