use std::thread;

// Define a multi-stage data processing pipeline
fn main() {
    // Create channels for communication between pipeline stages
    let (input_tx, input_rx) = mpsc::channel();
    let (processing_tx, processing_rx) = mpsc::channel();
    let (output_tx, output_rx) = mpsc::channel();

    // Spawn threads for each stage of the pipeline
    thread::spawn(move || {
        // Input stage: Enqueue data into the pipeline
        input_tx.send(0).unwrap();
    });

    for _ in 0..8 {
        let processing_rx = processing_rx.clone();
        let processing_tx = processing_tx.clone();
        // Processing stage: Process data and enqueue the result
        thread::spawn(move || {
            while let Ok(data) = processing_rx.recv() {
                let result = data * 2; // Example processing operation
                processing_tx.send(result).unwrap();
            }
        });
    }

    thread::spawn(move || {
        // Output stage: Receive processed data and perform the final output operation
        while let Ok(data) = output_rx.recv() {
            println!("Processed data: {}", data);
        }
    });

    // Connect the stages of the pipeline
    let mut input_tx = Some(input_tx);
    for processing_tx in vec![processing_tx; 8] {
        let next_input_tx = input_tx.take().unwrap();
        let next_processing_tx = processing_tx.clone();
        thread::spawn(move || {
            while let Ok(data) = next_input_tx.recv() {
                next_processing_tx.send(data).unwrap();
            }
        });
        input_tx = Some(processing_tx);
    }
    let output_tx = input_tx.take().unwrap();

    // Start the pipeline by enqueuing initial data
    output_tx.send(0).unwrap();

    // Wait for all threads to finish
    thread::sleep(std::time::Duration::from_secs(1));
}

