    let mut field_count = 0;
    for field in fields {
        let key_value: Vec<&str> = field.split(':').collect();
        if key_value.len() == 2 {
            let key = key_value[0];
            let value = key_value[1];
            match key {
                "byr" => {
                    if let Ok(year) = value.parse::<i32>() {
                        if year >= 1920 && year <= 2002 {
                            field_count += 1;
                        }
                    }
