fn process_accounts(num_table_loaded_accounts: Vec<u32>) -> Result<u32, SanitizeError> {
    let mut num_loaded_accounts: u32 = 0;

    for &accounts in &num_table_loaded_accounts {
        if accounts == 0 {
            return Err(SanitizeError::InvalidValue);
        }
        num_loaded_accounts = num_loaded_accounts.saturating_add(accounts);
    }

    Ok(num_loaded_accounts)
}

