extern crate hmacsha1;
extern crate base32;
extern crate chrono;

use hmacsha1::hmac_sha1;
use base32;
use chrono::prelude::*;

const T0: i64 = 0;
const T: i64 = 30;
const DIGITS: usize = 6;

pub struct TOTP {
    secret_key: Vec<u8>,
    time_step: i64,
}

impl TOTP {
    pub fn new(secret_key: &str, time_step: Option<i64>) -> TOTP {
        let time_step = time_step.unwrap_or(30);
        TOTP {
            secret_key: base32::decode(base32::Alphabet::RFC4648 { padding: false }, secret_key).unwrap(),
            time_step,
        }
    }

    pub fn generate(&self) -> String {
        let current_time = Utc::now().timestamp();
        let counter = (current_time - T0) / self.time_step;
        let counter_bytes: [u8; 8] = unsafe { std::mem::transmute(counter.to_be()) };
        let hmac = hmac_sha1(&self.secret_key, &counter_bytes);
        let offset = (hmac[hmac.len() - 1] & 0xf) as usize;
        let binary = ((hmac[offset] & 0x7f) as u32) << 24
            | ((hmac[offset + 1] & 0xff) as u32) << 16
            | ((hmac[offset + 2] & 0xff) as u32) << 8
            | (hmac[offset + 3] & 0xff) as u32;
        let otp = binary % 10_u32.pow(DIGITS as u32);
        format!("{:01$}", otp, DIGITS)
    }
}

