use bytes::{Bytes, BytesMut};
use std::result::Result;

pub struct OpusPayloader;

impl Payloader for OpusPayloader {
    fn payload(&self, mtu: usize, payload: &Bytes) -> Result<Vec<Bytes>, Error> {
        if payload.is_empty() || mtu == 0 {
            return Ok(vec![]);
        }

        let mut payloads = Vec::new();
        let mut remaining_payload = payload.clone();

        while !remaining_payload.is_empty() {
            let chunk_size = remaining_payload.len().min(mtu);
            let chunk = remaining_payload.split_to(chunk_size);
            payloads.push(chunk.freeze());
        }

        Ok(payloads)
    }
}

