    }

    // Transfer funds to another account
    fn transfer_funds(&mut self, recipient: &mut BankAccount, amount: f64) -> Result<(), &'static str> {
        if self.balance >= amount {
            self.balance -= amount;
            recipient.balance += amount;
            Ok(())
        } else {
            Err("Insufficient balance")
        }
    }
}

