use rand::{thread_rng, Rng};
use std::{thread, time};
use term_size;

fn generate_consonant_string() -> Result<String, String> {
    let mut width = 0;
    if let Some((w, _)) = term_size::dimensions() {
        width = w;
    } else {
        return Err(String::from("Unable to get term size :("));
    }

    let consonants = "bcdfghjklmnpqrstvwxyz     ";
    let mut rng = rand::thread_rng();

    let mut result = String::new();
    let mut current_length = 0;

    while current_length < width {
        let next_char = consonants.chars().nth(rng.gen_range(0, consonants.len())).unwrap();
        if next_char != ' ' || current_length + 1 < width {
            result.push(next_char);
            current_length += 1;
        }
    }

    Ok(result)
}

fn main() {
    match generate_consonant_string() {
        Ok(s) => println!("{}", s),
        Err(e) => println!("{}", e),
    }
}

