use core::panic::PanicInfo;

// Define the PanicInfo type
#[panic_handler]
fn panic(info: &PanicInfo) -> ! {
    if let Some(location) = info.location() {
        serial_println!("Panic in file '{}' at line {}", location.file(), location.line());
    } else {
        serial_println!("Panic location unknown");
    }
    if let Some(message) = info.message() {
        serial_println!("Panic message: {}", message);
    } else {
        serial_println!("No panic message");
    }
    exit_qemu(QemuExitCode::Failure);
    loop {}
}

// Implement the exit_qemu function
enum QemuExitCode {
    Success = 0x10,
    Failure = 0x11,
}

fn exit_qemu(code: QemuExitCode) {
    use x86_64::instructions::port::Port;

    unsafe {
        let mut port = Port::new(0xf4);
        port.write(code as u32);
    }
}

