    fn new() -> TvRatings {
        TvRatings {
            ratings: HashMap::new(),
        }
    }

    fn add_rating(&mut self, show: &str, rating: f64) {
        self.ratings.insert(show.to_string(), rating);
    }

    fn get_rating(&self, show: &str) -> Option<&f64> {
        self.ratings.get(show)
    }

    fn iter_all_ratings(&self) -> Vec<(&String, &f64)> {
        self.ratings.iter().collect()
    }

    fn iter_all_ratings_mut(&mut self) -> Vec<(&String, &mut f64)> {
        self.ratings.iter_mut().collect()
    }
}

impl fmt::Display for TvRatings {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for (show, rating) in &self.ratings {
            write!(f, "{}: {}\n", show, rating)?;
        }
        Ok(())
    }
}

