pub mod books {
    use super::Book;

    // Define a vector to store the books
    lazy_static::lazy_static! {
        static ref BOOKS: std::sync::Mutex<Vec<Book>> = std::sync::Mutex::new(Vec::new());
    }

    // Function to add a new book to the library
    pub fn add_book(title: String, author: String) {
        let mut books = BOOKS.lock().unwrap();
        books.push(Book::new(title, author));
    }

    // Function to remove a book from the library
    pub fn remove_book(title: &str) {
        let mut books = BOOKS.lock().unwrap();
        books.retain(|book| book.title != title);
    }

    // Function to find a book by title
    pub fn find_book_by_title(title: &str) -> Option<Book> {
        let books = BOOKS.lock().unwrap();
        books.iter().find(|&book| book.title == title).cloned()
    }

    // Function to find books by author
    pub fn find_books_by_author(author: &str) -> Vec<Book> {
        let books = BOOKS.lock().unwrap();
        books.iter().filter(|&book| book.author == author).cloned().collect()
    }

    // Function to list all books in the library
    pub fn list_all_books() -> Vec<Book> {
        let books = BOOKS.lock().unwrap();
        books.clone()
    }
}

