use std::fmt::Debug;

// Define a custom Future trait with expect_ok and expect_err methods
trait Future {
    type Output;
    type Error;

    // Polls the future and returns the result
    fn expect_ready(&mut self) -> Result<Self::Output, Self::Error>;

    // Polls the future and asserts that the result is Ok(_) - and returns the value after unwrapping
    fn expect_ok(&mut self) -> Self::Output
    where
        Self::Output: Debug,
    {
        match self.expect_ready() {
            Ok(value) => value,
            Err(_) => panic!("Expected future to yield an Ok(_) result."),
        }
    }

    // Polls the future and asserts that the result is Err(_) - and returns the error after unwrapping
    fn expect_err(&mut self) -> Self::Error
    where
        Self::Output: Debug,
    {
        match self.expect_ready() {
            Err(error) => error,
            Ok(_) => panic!("Expected future to yield an Err(_) result."),
        }
    }
}

// Example implementation of a custom Future
struct CustomFuture<T, E> {
    result: Result<T, E>,
}

impl<T, E> Future for CustomFuture<T, E> {
    type Output = T;
    type Error = E;

    fn expect_ready(&mut self) -> Result<Self::Output, Self::Error> {
        self.result.take().unwrap()
    }
}

fn main() {
    let mut future_ok = CustomFuture {
        result: Ok("Success"),
    };
    let mut future_err = CustomFuture {
        result: Err("Error"),
    };

    // Test expect_ok method
    assert_eq!(future_ok.expect_ok(), "Success");

    // Test expect_err method
    assert_eq!(future_err.expect_err(), "Error");
}

