fn resolve_dependencies(packages: &[(String, Vec<String>)]) -> Result<Vec<String>, String> {
    let mut graph: HashMap<String, Vec<String>> = HashMap::new();
    let mut indegree: HashMap<String, usize> = HashMap::new();

    // Build the dependency graph and calculate the indegree of each package
    for (package, dependencies) in packages {
        graph.entry(package.clone()).or_insert(Vec::new());
        indegree.entry(package.clone()).or_insert(0);
        for dep in dependencies {
            graph.entry(dep.clone()).or_insert(Vec::new()).push(package.clone());
            *indegree.entry(package.clone()).or_insert(0) += 1;
        }
    }

    let mut queue: Vec<String> = Vec::new();
    let mut result: Vec<String> = Vec::new();

    // Initialize the queue with packages having zero indegree
    for (package, degree) in indegree.iter() {
        if *degree == 0 {
            queue.push(package.clone());
        }
    }

    while !queue.is_empty() {
        let current = queue.pop().unwrap();
        result.push(current.clone());

        if let Some(dependents) = graph.get(&current) {
            for dependent in dependents {
                let new_degree = indegree.get_mut(dependent).unwrap() - 1;
                if new_degree == 0 {
                    queue.push(dependent.clone());
                }
                *indegree.get_mut(dependent).unwrap() = new_degree;
            }
        }
    }

    if result.len() != graph.len() {
        return Err("Cyclic dependency detected".to_string());
    }

    Ok(result)
}

