pub struct Account {
    balance: f64,
    max_withdrawal: f64,
}

pub struct Withdrawal {
    amount: f64,
    timestamp: u64,
}

impl Account {
    pub fn withdrawal(&self, amount: f64, timestamp: u64) -> Option<Withdrawal> {
        if amount > self.balance {
            return None; // Insufficient funds
        }
        if amount > self.max_withdrawal {
            return None; // Exceeds maximum withdrawal limit
        }

        self.balance -= amount;
        Some(Withdrawal { amount, timestamp })
    }
}

fn main() {
    let account = Account {
        balance: 1000.0,
        max_withdrawal: 500.0,
    };

    // Attempt a withdrawal
    match account.withdrawal(300.0, 123456789) {
