fn jit_function_execution(x: i32, y: i32) -> i32 {
    let ctx = jit_context_create();
    let sig = jit_type_create_signature(
        jit_abi_cdecl, 
        jit_type_int, 
        vec![jit_type_int, jit_type_int]
    );
    let func = jit_function_create(ctx, sig);

    let x_param = jit_value_get_param(func, 0);
    let y_param = jit_value_get_param(func, 1);

    let temp = jit_insn_add(func, x_param, y_param);
    jit_insn_return(func, temp);

    jit_function_compile(func);
    jit_context_build_end(ctx);

    let arg_values: Vec<i32> = vec![x, y];
    let arg_ptrs: Vec<*const i32> = arg_values.iter().map(|p| p as *const i32).collect();
    let mut result: i32 = 0;

    unsafe {
        let result_ptr: *mut i32 = &mut result;
        jit_function_apply(func, arg_ptrs.as_ptr(), result_ptr as *mut _);
    }

    result
}

