use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct LPassError {
    message: String,
    source: Option<Box<dyn Error>>,
}

impl LPassError {
    fn new(message: &str, source: Option<Box<dyn Error>>) -> LPassError {
        LPassError {
            message: message.to_string(),
            source,
        }
    }
}

impl fmt::Display for LPassError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl Error for LPassError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        self.source.as_ref().map(|e| e.as_ref())
    }
}

fn exec_lpass(args: &[&str]) -> Result<String, LPassError> {
    match Command::new("lpass").args(args.iter()).output() {
        Ok(output) => {
            if output.status.success() {
                let password = String::from_utf8(output.stdout).map_err(|e| LPassError::new("Invalid UTF-8 sequence in output", Some(Box::new(e))))?;
                Ok(password.trim().to_string())
            } else {
                let error_message = String::from_utf8(output.stderr).unwrap_or_else(|_| "Unknown error".to_string());
                Err(LPassError::new(&error_message, None))
            }
        }
        Err(err) => Err(LPassError::new("Could not exec command", Some(Box::new(err))))
    }
}

fn get_lastpass_password(account_name: &str) -> Result<String, LPassError> {
    let args = ["show", "-p", account_name];
    exec_lpass(&args)
}

