use std::time::{Duration, Instant};
use std::collections::HashMap;

struct TimeoutManager {
    id_counter: u64,
    timeouts: HashMap<u64, Instant>,
}

impl TimeoutManager {
    fn new() -> TimeoutManager {
        TimeoutManager {
            id_counter: 0,
            timeouts: HashMap::new(),
        }
    }

    fn set_timeout<F>(&mut self, task: F, duration_ms: u64) -> u64
    where
        F: FnOnce(),
    {
        let id = self.id_counter;
        self.id_counter += 1;
        let deadline = Instant::now() + Duration::from_millis(duration_ms);
        self.timeouts.insert(id, deadline);

        let cloned_id = id;
        let timeouts_ref = &mut self.timeouts;
        std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(duration_ms));
            if let Some(time) = timeouts_ref.get(&cloned_id) {
                if Instant::now() >= *time {
                    task();
                    timeouts_ref.remove(&cloned_id);
                }
            }
        });

        id
    }

    fn clear_timeout(&mut self, id: u64) {
        self.timeouts.remove(&id);
    }
}

