use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, DeriveInput};

#[proc_macro_derive(MyDebug, attributes(derivative))]
pub fn my_debug(input: TokenStream) -> TokenStream {
    let ast = parse_macro_input!(input as DeriveInput);
    let name = &ast.ident;

    let format_with = ast.attrs.iter().find_map(|attr| {
        if let Ok(meta) = attr.parse_meta() {
            if meta.path().is_ident("derivative") {
                if let syn::Meta::List(list) = meta {
                    for nested in list.nested {
                        if let syn::NestedMeta::Meta(syn::Meta::NameValue(name_value)) = nested {
                            if name_value.path.is_ident("Debug") {
                                if let syn::Lit::Str(ref s) = name_value.lit {
                                    return Some(s.value());
                                }
                            }
                        }
                    }
                }
            }
        }
        None
    });

    let gen = quote! {
        impl std::fmt::Debug for #name {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                #format_with(f, &self.v)
            }
        }
    };

    gen.into()
}

