async fn calculate_directory_size(dir_path: &str) -> Result<usize, std::io::Error> {
    let mut size: usize = 0;

    let mut entries = fs::read_dir(dir_path).await?; // Read the directory entries asynchronously

    while let Some(entry) = entries.next_entry().await? { // Iterate through each directory entry
        if entry.file_type().await?.is_file() { // Check if the entry is a file
            let metadata = tokio::fs::metadata(entry.path()).await?; // Retrieve the metadata of the file
            size += metadata.len() as usize; // Add the file size to the running total
        }
    }

    Ok(size) // Return the total size of all files within the directory
}

