fn fragment_packet(packet: &[u8], mtu: usize) -> Vec<Vec<u8>> {
    let mut fragmented_packets = Vec::new();
    let mut remaining_data = packet;

    while !remaining_data.is_empty() {
        let chunk_size = if remaining_data.len() > mtu {
            mtu
        } else {
            remaining_data.len()
        };

        let (current_chunk, rest) = remaining_data.split_at(chunk_size);
        fragmented_packets.push(current_chunk.to_vec());
        remaining_data = rest;
    }

    fragmented_packets
}

