impl VestingSchedule {
    fn get_vested_coins(&self, current_time: u64) -> u64 {
        if current_time < self.start_time {
            return 0; // No coins vested before the start time
        }

        let elapsed_time = current_time - self.start_time;
        if elapsed_time >= self.duration {
            return self.total_amount; // All coins vested after the duration
        }

        let num_intervals = elapsed_time / self.interval;
        let vested_coins = num_intervals * self.amount_per_interval;

        if vested_coins > self.total_amount {
            return self.total_amount; // Return the total amount if vested coins exceed the total
        }

        vested_coins
    }
}

