use std::ptr;

struct CustomRc<T> {
    data: *const T,
    reference_count: *mut usize,
}

impl<T> CustomRc<T> {
    fn new(data: T) -> Self {
        let boxed_data = Box::new(data);
        let reference_count = Box::new(1);

        CustomRc {
            data: Box::into_raw(boxed_data),
            reference_count: Box::into_raw(reference_count),
        }
    }

    fn clone(&self) -> Self {
        unsafe {
            *self.reference_count += 1;
        }
        CustomRc {
            data: self.data,
            reference_count: self.reference_count,
        }
    }
}

impl<T> Drop for CustomRc<T> {
    fn drop(&mut self) {
        unsafe {
            if *self.reference_count == 1 {
                ptr::drop_in_place(self.data as *mut T);
                Box::from_raw(self.reference_count);
            } else {
                *self.reference_count -= 1;
            }
        }
    }
}

fn main() {
    let custom_rc1 = CustomRc::new(42);
    let custom_rc2 = custom_rc1.clone();
    let custom_rc3 = custom_rc2.clone();

    drop(custom_rc2);
    drop(custom_rc3);
    // custom_rc1 will deallocate the resource when it goes out of scope
}

