pub enum Status {
    Pending,
    InProgress,
    Completed,
    Failed,
}

pub struct Job {
    id: u64,
    status: Status,
    duration: Duration,
}

pub struct JobManager {
    jobs: HashMap<u64, Job>,
}

impl JobManager {
    pub fn new() -> JobManager {
        JobManager {
            jobs: HashMap::new(),
        }
    }

    pub fn add_job(&mut self, id: u64, status: Status, duration: Duration) {
        let job = Job { id, status, duration };
        self.jobs.insert(id, job);
    }

    pub fn get_job_status(&self, id: u64) -> Option<&Status> {
        if let Some(job) = self.jobs.get(&id) {
            Some(&job.status)
        } else {
            None
        }
    }

    pub fn update_job_status(&mut self, id: u64, new_status: Status) -> bool {
        if let Some(job) = self.jobs.get_mut(&id) {
            job.status = new_status;
            true
        } else {
            false
        }
    }

    pub fn get_average_duration(&self) -> Option<Duration> {
        let completed_jobs: Vec<&Job> = self.jobs.values().filter(|job| job.status == Status::Completed).collect();
        if completed_jobs.is_empty() {
            None
        } else {
            let total_duration: Duration = completed_jobs.iter().map(|job| &job.duration).sum();
            let average_duration = Duration {
                hours: total_duration.hours / completed_jobs.len() as u32,
                minutes: total_duration.minutes / completed_jobs.len() as u32,
                seconds: total_duration.seconds / completed_jobs.len() as u32,
            };
            Some(average_duration)
        }
    }
}

