enum MidiMessage {
    NoteOn(u8, u8),  // Represents a note on message with note number and velocity
    NoteOff(u8, u8), // Represents a note off message with note number and velocity
    ControlChange(u8, u8), // Represents a control change message with controller number and value
    // Add other MIDI message types as needed
}

// Define a function to parse raw MIDI messages
fn parse_midi_message(raw_message: &[u8]) -> Option<MidiMessage> {
    if raw_message.is_empty() {
        return None;
    }
    match raw_message[0] & 0xF0 {
        0x80 => {
            if raw_message.len() >= 3 {
                Some(MidiMessage::NoteOff(raw_message[1], raw_message[2]))
            } else {
                None
            }
        }
        0x90 => {
            if raw_message.len() >= 3 {
                Some(MidiMessage::NoteOn(raw_message[1], raw_message[2]))
            } else {
                None
            }
        }
        0xB0 => {
            if raw_message.len() >= 3 {
                Some(MidiMessage::ControlChange(raw_message[1], raw_message[2]))
            } else {
                None
            }
        }
        _ => None,
    }
}

// Define functions to process MIDI messages
fn process_note_on(message: MidiMessage) {
    if let MidiMessage::NoteOn(note, velocity) = message {
        // Process note on message
        println!("Note On: Note={}, Velocity={}", note, velocity);
    }
}

fn process_note_off(message: MidiMessage) {
    if let MidiMessage::NoteOff(note, velocity) = message {
        // Process note off message
        println!("Note Off: Note={}, Velocity={}", note, velocity);
    }
}

fn process_control_change(message: MidiMessage) {
    if let MidiMessage::ControlChange(controller, value) = message {
        // Process control change message
        println!("Control Change: Controller={}, Value={}", controller, value);
    }
}

// Example usage
fn main() {
    let raw_message = [0x90, 60, 100]; // Example raw MIDI message (Note On: Note=60, Velocity=100)
    if let Some(parsed_message) = parse_midi_message(&raw_message) {
        process_note_on(parsed_message);
    }
}

