use std::thread;

struct MovieTheater {
    available_seats: usize,
}

impl MovieTheater {
    fn new(seats: usize) -> Self {
        MovieTheater {
            available_seats: seats,
        }
    }

    fn purchase_ticket(&mut self) -> bool {
        if self.available_seats > 0 {
            self.available_seats -= 1;
            true
        } else {
            false
        }
    }
}

