    let mut handles = vec![];

    for _ in 0..20 {
        let theater = Arc::clone(&theater);
        let handle = thread::spawn(move || {
            let mut theater = theater.lock().unwrap();
            if theater.purchase_ticket() {
                println!("Ticket purchased. Remaining seats: {}", theater.available_seats);
            } else {
                println!("All seats sold out.");
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }
}

