const ROUNDS: usize = 20;

pub struct ChaCha {
    state: [u32; 16],
}

impl ChaCha {
    pub fn new(key: [u8; 32], nonce: [u8; 8]) -> ChaCha {
        let mut state = [0u32; 16];
        state[0] = 0x61707865;
        state[1] = 0x3320646e;
        state[2] = 0x79622d32;
        state[3] = 0x6b206574;
        for i in 0..8 {
            state[4 + i] = u32::from_le_bytes([
                key[i * 4],
                key[i * 4 + 1],
                key[i * 4 + 2],
                key[i * 4 + 3],
            ]);
        }
        for i in 0..2 {
            state[12 + i] = u32::from_le_bytes([nonce[i * 4], nonce[i * 4 + 1], nonce[i * 4 + 2], nonce[i * 4 + 3]]);
        }
        ChaCha { state }
    }

    pub fn encrypt(&mut self, counter: u32) -> [u8; 64] {
        let mut state = self.state;
        state[12] += counter;
        state[13] += if state[12] < counter { 1 } else { 0 };
        Self::chacha_rounds(&mut state);
        let mut output = [0u8; 64];
        for i in 0..16 {
            output[i * 4..(i + 1) * 4].copy_from_slice(&state[i].to_le_bytes());
        }
        output
    }

    fn chacha_rounds(state: &mut [u32; 16]) {
        let mut x = *state;
        for _ in 0..ROUNDS / 2 {
            Self::quarter_rounds(&mut x, 0, 4, 8, 12);
            Self::quarter_rounds(&mut x, 1, 5, 9, 13);
            Self::quarter_rounds(&mut x, 2, 6, 10, 14);
            Self::quarter_rounds(&mut x, 3, 7, 11, 15);
            Self::quarter_rounds(&mut x, 0, 5, 10, 15);
            Self::quarter_rounds(&mut x, 1, 6, 11, 12);
            Self::quarter_rounds(&mut x, 2, 7, 8, 13);
            Self::quarter_rounds(&mut x, 3, 4, 9, 14);
        }
        for i in 0..16 {
            state[i] = state[i].wrapping_add(x[i]);
        }
    }

    fn quarter_rounds(x: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
        x[a] = x[a].wrapping_add(x[b]);
        x[d] = (x[d] ^ x[a]).rotate_left(16);
        x[c] = x[c].wrapping_add(x[d]);
        x[b] = (x[b] ^ x[c]).rotate_left(12);
        x[a] = x[a].wrapping_add(x[b]);
        x[d] = (x[d] ^ x[a]).rotate_left(8);
        x[c] = x[c].wrapping_add(x[d]);
        x[b] = (x[b] ^ x[c]).rotate_left(7);
    }
}

