use ggez::{Context, GameResult};
use ggez::event;
use ggez::graphics::{self, Color, DrawMode, Rect};
use ggez::input::keyboard;
use ggez::nalgebra as na;

const WINDOW_WIDTH: f32 = 800.0;
const WINDOW_HEIGHT: f32 = 600.0;
const PADDLE_WIDTH: f32 = 10.0;
const PADDLE_HEIGHT: f32 = 100.0;
const PADDLE_SPEED: f32 = 5.0;
const BALL_SIZE: f32 = 10.0;
const BALL_SPEED: f32 = 2.0;

struct Paddle {
    position: na::Point2<f32>,
    velocity: f32,
}

struct Ball {
    position: na::Point2<f32>,
    velocity: na::Vector2<f32>,
}

struct GameState {
    player1: Paddle,
    player2: Paddle,
    ball: Ball,
    player1_score: u32,
    player2_score: u32,
}

impl event::EventHandler for GameState {
    fn update(&mut self, _ctx: &mut Context) -> GameResult {
        // Update ball position
        self.ball.position += self.ball.velocity;

        // Check for collision with walls
        if self.ball.position.y <= 0.0 || self.ball.position.y >= WINDOW_HEIGHT - BALL_SIZE {
            self.ball.velocity.y = -self.ball.velocity.y;
        }

        // Check for collision with paddles
        if self.ball.position.x <= PADDLE_WIDTH && self.ball.position.y >= self.player1.position.y
            && self.ball.position.y <= self.player1.position.y + PADDLE_HEIGHT {
            self.ball.velocity.x = -self.ball.velocity.x;
        } else if self.ball.position.x >= WINDOW_WIDTH - PADDLE_WIDTH - BALL_SIZE
            && self.ball.position.y >= self.player2.position.y
            && self.ball.position.y <= self.player2.position.y + PADDLE_HEIGHT {
            self.ball.velocity.x = -self.ball.velocity.x;
        }

        // Check for scoring
        if self.ball.position.x <= 0.0 {
            self.player2_score += 1;
            self.reset_ball();
        } else if self.ball.position.x >= WINDOW_WIDTH - BALL_SIZE {
            self.player1_score += 1;
            self.reset_ball();
        }

        Ok(())
    }

    fn draw(&mut self, ctx: &mut Context) -> GameResult {
        graphics::clear(ctx, Color::BLACK);

        // Draw paddles
        let paddle1_rect = Rect::new(
            self.player1.position.x,
            self.player1.position.y,
            PADDLE_WIDTH,
            PADDLE_HEIGHT,
        );
        let paddle2_rect = Rect::new(
            self.player2.position.x,
            self.player2.position.y,
            PADDLE_WIDTH,
            PADDLE_HEIGHT,
        );
        let paddle_color = Color::WHITE;
        graphics::draw(ctx, &paddle1_rect, DrawMode::Fill, paddle_color)?;
        graphics::draw(ctx, &paddle2_rect, DrawMode::Fill, paddle_color)?;

        // Draw ball
        let ball_rect = Rect::new(self.ball.position.x, self.ball.position.y, BALL_SIZE, BALL_SIZE);
        let ball_color = Color::WHITE;
        graphics::draw(ctx, &ball_rect, DrawMode::Fill, ball_color)?;

        // Draw scores
        let score_text = graphics::Text::new(format!("{}   {}", self.player1_score, self.player2_score));
        graphics::draw(ctx, &score_text, (na::Point2::new(380.0, 10.0), 0.0, Color::WHITE))?;

        graphics::present(ctx)?;
        Ok(())
    }

    fn key_down_event(&mut self, _ctx: &mut Context, keycode: keyboard::KeyCode, _keymod: keyboard::KeyMods, _repeat: bool) {
        match keycode {
            keyboard::KeyCode::W => {
                if self.player1.position.y > 0.0 {
                    self.player1.position.y -= PADDLE_SPEED;
                }
            }
            keyboard::KeyCode::S => {
                if self.player1.position.y < WINDOW_HEIGHT - PADDLE_HEIGHT {
                    self.player1.position.y += PADDLE_SPEED;
                }
            }
            keyboard::KeyCode::Up => {
                if self.player2.position.y > 0.0 {
                    self.player2.position.y -= PADDLE_SPEED;
                }
            }
            keyboard::KeyCode::Down => {
                if self.player2.position.y < WINDOW_HEIGHT - PADDLE_HEIGHT {
                    self.player2.position.y += PADDLE_SPEED;
                }
            }
            _ => (),
        }
    }
}

impl GameState {
    fn reset_ball(&mut self) {
        self.ball.position = na::Point2::new(WINDOW_WIDTH / 2.0 - BALL_SIZE / 2.0, WINDOW_HEIGHT / 2.0 - BALL_SIZE / 2.0);
        self.ball.velocity = na::Vector2::new(-BALL_SPEED, BALL_SPEED);
    }
}

pub fn run() {
    let (ctx, event_loop) = ggez::ContextBuilder::new("rust_pong", "ggez")
        .window_setup(ggez::conf::WindowSetup::default().title("Pong"))
        .window_mode(ggez::conf::WindowMode::default().dimensions(WINDOW_WIDTH, WINDOW_HEIGHT))
        .build()
        .unwrap();

    let game_state = GameState {
        player1: Paddle {
            position: na::Point2::new(10.0, WINDOW_HEIGHT / 2.0 - PADDLE_HEIGHT / 2.0),
            velocity: 0.0,
        },
        player2: Paddle {
            position: na::Point2::new(WINDOW_WIDTH - PADDLE_WIDTH - 10.0, WINDOW_HEIGHT / 2.0 - PADDLE_HEIGHT / 2.0),
            velocity: 0.0,
        },
        ball: Ball {
            position: na::Point2::new(WINDOW_WIDTH / 2.0 - BALL_SIZE / 2.0, WINDOW_HEIGHT / 2.0 - BALL_SIZE / 2.0),
            velocity: na::Vector2::new(-BALL_SPEED, BALL_SPEED),
        },
        player1_score: 0,
        player2_score: 0,
    };

    event::run(ctx, event_loop, game_state);
}

