use rust_decimal::Decimal;

struct Fill {
    base_value: Decimal,
    quote_value: Decimal,
    exhausted: bool,
}

impl Fill {
    pub fn ask_volume(&self, price_limit: &Decimal, current_price: &Decimal) -> Fill {
        let mut base_value = Decimal::zero();
        let mut quote_value = Decimal::zero();
        let mut exhausted = false;

        if *price_limit <= Decimal::zero() {
            return Fill {
                base_value,
                quote_value,
                exhausted: true,
            };
        }

        let mut remaining_quote_value = *price_limit;

        // Calculate the volume based on the price limit and current price
        if *current_price > Decimal::zero() {
            let volume = remaining_quote_value / *current_price;
            base_value += volume;
            quote_value += remaining_quote_value;
            remaining_quote_value = Decimal::zero(); // Order execution is exhausted
        } else {
            exhausted = true; // Current price is zero, order execution is exhausted
        }

        Fill {
            base_value,
            quote_value,
            exhausted,
        }
    }
}

