use rand::prelude::*;

struct SimulationResult {
    win: bool,
    switch: bool,
}

fn simulate(random_door: &u8, rng: &mut ThreadRng) -> SimulationResult {
    let prize_door = rng.gen_range(1, 4);
    let contestant_switches = rng.gen_bool(0.5);

    let win = *random_door == prize_door;
    let switch = if contestant_switches {
        !win
    } else {
        win
    };

    SimulationResult { win, switch }
}

fn main() {
    let mut rng = thread_rng();
    let mut random_door: u8;

    let mut switch_wins = 0;
    let mut keep_wins = 0;
    let mut switch_losses = 0;
    let mut keep_losses = 0;

    for _ in 0..1000 {
        random_door = rng.gen_range(1, 4);
        let result = simulate(&random_door, &mut rng);

        match (result.win, result.switch) {
            (true, true) => switch_wins += 1,
            (true, false) => keep_wins += 1,
            (false, true) => switch_losses += 1,
            (false, false) => keep_losses += 1,
        }
    }

    println!("Switch wins: {}", switch_wins);
    println!("Keep wins: {}", keep_wins);
    println!("Switch losses: {}", switch_losses);
    println!("Keep losses: {}", keep_losses);
}

