use std::io::{Read, Error as IoError};
use hyper::StatusCode;

struct ApiResponseError {
    status: StatusCode,
    message: String,
    body: String,
}

impl ApiResponseError {
    fn from_response(status: StatusCode, mut response: &mut dyn Read) -> Result<(), ApiResponseError> {
        let mut body = String::new();
        match response.read_to_string(&mut body) {
            Err(err) => {
                return Err(ApiResponseError {
                    status: status.clone(),
                    message: format!("Error reading response: {}", err),
                    body: "".to_owned(),
                });
            }
            _ => {}
        }

        if !status.is_success() {
            let reason_phrase = status.canonical_reason().unwrap_or("Unknown");
            let error_message = format!("Error: {} - {}. Response: {}", status.as_u16(), reason_phrase, body);
            return Err(ApiResponseError {
                status: status.clone(),
                message: error_message,
                body: body,
            });
        }

        Ok(())
    }
}

