use std::collections::HashSet;

#[derive(Debug, PartialEq)]
pub struct CustomSet<T: Eq + std::hash::Hash> {
    elements: HashSet<T>,
}

impl<T: Eq + std::hash::Hash> CustomSet<T> {
    pub fn new() -> Self {
        CustomSet {
            elements: HashSet::new(),
        }
    }

    pub fn add(&mut self, element: T) {
        self.elements.insert(element);
    }

    pub fn remove(&mut self, element: &T) {
        self.elements.remove(element);
    }

    pub fn contains(&self, element: &T) -> bool {
        self.elements.contains(element)
    }

    pub fn size(&self) -> usize {
        self.elements.len()
    }

    pub fn union(&self, other: &CustomSet<T>) -> CustomSet<T> {
        let new_elements: HashSet<T> = self.elements.union(&other.elements).cloned().collect();
        CustomSet {
            elements: new_elements,
        }
    }
}

impl<T: Eq + std::hash::Hash> From<Vec<T>> for CustomSet<T> {
    fn from(vec: Vec<T>) -> Self {
        let elements: HashSet<T> = vec.into_iter().collect();
        CustomSet { elements }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add_element() {
        let mut set: CustomSet<i32> = CustomSet::new();
        set.add(1);
        set.add(2);
        assert_eq!(set.size(), 2);
    }

    #[test]
    fn test_remove_element() {
        let mut set: CustomSet<i32> = CustomSet::from(vec![1, 2, 3]);
        set.remove(&2);
        assert!(!set.contains(&2));
    }

    #[test]
    fn test_union() {
        let set1: CustomSet<i32> = CustomSet::from(vec![1, 2, 3]);
        let set2: CustomSet<i32> = CustomSet::from(vec![3, 4, 5]);
        let union_set = set1.union(&set2);
        assert_eq!(union_set.size(), 5);
    }
}

