use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll, Waker, RawWaker, RawWakerVTable};
use std::cell::RefCell;
use std::rc::Rc;

/// A future that becomes ready after a tick of the micro task queue.
pub struct NextTick {
    inner: Option<Rc<RefCell<Option<Waker>>>>,
}

impl NextTick {
    /// Construct a new `NextTick` future.
    pub fn new() -> NextTick {
        NextTick {
            inner: Some(Rc::new(RefCell::new(None))),
        }
    }

    /// Wait for the future to become ready.
    pub fn await(&self) {
        let waker = futures::task::noop_waker();
        let mut context = Context::from_waker(&waker);
        loop {
            if self.inner.borrow().is_some() {
                if let Poll::Ready(_) = self.poll_unpin(&mut context) {
                    break;
                }
            }
        }
    }

    fn poll_unpin(&self, cx: &mut Context) -> Poll<()> {
        if let Some(waker) = self.inner.clone() {
            *waker.borrow_mut() = Some(cx.waker().clone());
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}

/// Schedule a task to be executed on the next tick of the micro task queue.
pub fn schedule_task<F: FnOnce() + 'static>(task: F) {
    let waker = futures::task::noop_waker();
    let mut context = Context::from_waker(&waker);
    let future = async {
        task();
    };
    let _ = Pin::new(&mut future).poll(&mut context);
}

