pub struct PressureField {
    buf: Vec<f64>,
    width: usize,
    height: usize,
}

impl PressureField {
    pub fn new(width: usize, height: usize) -> Self {
        Self {
            buf: vec![0.0; width * height],
            width,
            height,
        }
    }

    pub fn add_point_pressure(&mut self, x: usize, y: usize, pressure: f64) {
        if x < self.width && y < self.height {
            let index = y * self.width + x;
            self.buf[index] += pressure;
        }
    }

    pub fn get_pressure_at(&self, x: usize, y: usize) -> Option<f64> {
        if x < self.width && y < self.height {
            let index = y * self.width + x;
            Some(self.buf[index])
        } else {
            None
        }
    }

    pub fn visualize(&self) {
        for y in 0..self.height {
            for x in 0..self.width {
                if let Some(pressure) = self.get_pressure_at(x, y) {
                    print!("{}", match pressure {
                        p if p < 0.25 => '.',
                        p if p < 0.5 => 'o',
                        p if p < 0.75 => 'O',
                        _ => '#',
                    });
                } else {
                    print!("#"); // Out of bounds
                }
            }
            println!();
        }
    }
}

impl Default for PressureField {
    fn default() -> Self {
        Self::new(10, 10)
    }
}

