use std::collections::{BinaryHeap, HashMap};
use std::cmp::Ordering;

type NodeId = usize;
type Weight = i32;

#[derive(Clone, Copy, Eq, PartialEq)]
struct State {
    node: NodeId,
    cost: Weight,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

struct Graph {
    edges: HashMap<NodeId, Vec<(NodeId, Weight)>>,
}

impl Graph {
    fn new() -> Self {
        Graph { edges: HashMap::new() }
    }

    fn add_edge(&mut self, from: NodeId, to: NodeId, weight: Weight) {
        self.edges.entry(from).or_insert(Vec::new()).push((to, weight));
    }

    fn bidirectional_dijkstra(&self, source: NodeId, target: NodeId) -> Weight {
        let mut forward_dists = HashMap::new();
        let mut backward_dists = HashMap::new();
        let mut forward_heap = BinaryHeap::new();
        let mut backward_heap = BinaryHeap::new();

        forward_dists.insert(source, 0);
        forward_heap.push(State { node: source, cost: 0 });

        backward_dists.insert(target, 0);
        backward_heap.push(State { node: target, cost: 0 });

        let mut shortest_path = std::i32::MAX;

        while let Some(State { node: forward_node, cost: forward_cost }) = forward_heap.pop() {
            if let Some(&target_cost) = backward_dists.get(&forward_node) {
                shortest_path = shortest_path.min(forward_cost + target_cost);
            }

            if forward_cost > shortest_path {
                break;
            }

            if let Some(edges) = self.edges.get(&forward_node) {
                for &(next, weight) in edges {
                    let next_cost = forward_cost + weight;
                    if forward_dists.get(&next).map_or(true, |&dist| next_cost < dist) {
                        forward_dists.insert(next, next_cost);
                        forward_heap.push(State { node: next, cost: next_cost });
                    }
                }
            }
        }

        while let Some(State { node: backward_node, cost: backward_cost }) = backward_heap.pop() {
            if let Some(&source_cost) = forward_dists.get(&backward_node) {
                shortest_path = shortest_path.min(backward_cost + source_cost);
            }

            if backward_cost > shortest_path {
                break;
            }

            if let Some(edges) = self.edges.get(&backward_node) {
                for &(next, weight) in edges {
                    let next_cost = backward_cost + weight;
                    if backward_dists.get(&next).map_or(true, |&dist| next_cost < dist) {
                        backward_dists.insert(next, next_cost);
                        backward_heap.push(State { node: next, cost: next_cost });
                    }
                }
            }
        }

        shortest_path
    }
}

fn main() {
    let mut graph = Graph::new();
    graph.add_edge(1, 2, 1);
    graph.add_edge(2, 3, 2);
    graph.add_edge(3, 4, 3);
    graph.add_edge(4, 5, 4);
    graph.add_edge(5, 6, 5);
    graph.add_edge(6, 7, 6);

    let source = 1;
    let target = 7;

    let total_dist = graph.bidirectional_dijkstra(source, target);
    println!("Total distance of the shortest path from {} to {} is: {}", source, target, total_dist);
}

