use std::io::prelude::*;
use flate2::read::ZlibDecoder;

fn decompress_zlib(compressed_data: &[u8], uncompressed_size: usize) -> Result<Vec<u8>, String> {
    let mut decompressed_data = Vec::new();
    let mut decoder = ZlibDecoder::new(compressed_data);
    match decoder.read_to_end(&mut decompressed_data) {
        Ok(_) => {
            if decompressed_data.len() == uncompressed_size {
                Ok(decompressed_data)
            } else {
                Err(format!(
                    "ZLIB decompressed size {} does not match {}",
                    decompressed_data.len(),
                    uncompressed_size
                ))
            }
        }
        Err(err) => Err(format!("Decompression error: {}", err)),
    }
}

