// Define the PayloadManager struct to manage payload types and their IDs
pub struct PayloadManager {
    sendable_payloads: std::collections::HashMap<String, u8>,
    receivable_payloads: std::collections::HashMap<String, u8>,
}

impl PayloadManager {
    // Create a new instance of PayloadManager
    pub fn new() -> PayloadManager {
        PayloadManager {
            sendable_payloads: std::collections::HashMap::new(),
            receivable_payloads: std::collections::HashMap::new(),
        }
    }

    // Add a new payload type with its associated ID to the manager
    pub fn add_payload_type(&mut self, direction: &str, payload_type: &str, id: u8) -> Result<(), String> {
        match direction {
            "sendable" => {
                if self.sendable_payloads.contains_key(payload_type) {
                    Err(format!("Payload type '{}' already exists in sendable payloads", payload_type))
                } else {
                    self.sendable_payloads.insert(payload_type.to_string(), id);
                    Ok(())
                }
            }
            "receivable" => {
                if self.receivable_payloads.contains_key(payload_type) {
                    Err(format!("Payload type '{}' already exists in receivable payloads", payload_type))
                } else {
                    self.receivable_payloads.insert(payload_type.to_string(), id);
                    Ok(())
                }
            }
            _ => Err(format!("Invalid direction: {}", direction)),
        }
    }

    // Retrieve the ID associated with a given payload type and direction
    pub fn get_payload_id(&self, direction: &str, payload_type: &str) -> Result<u8, String> {
        match direction {
            "sendable" => {
                match self.sendable_payloads.get(payload_type) {
                    Some(&id) => Ok(id),
                    None => Err(format!("Payload type '{}' not found in sendable payloads", payload_type)),
                }
            }
            "receivable" => {
                match self.receivable_payloads.get(payload_type) {
                    Some(&id) => Ok(id),
                    None => Err(format!("Payload type '{}' not found in receivable payloads", payload_type)),
                }
            }
            _ => Err(format!("Invalid direction: {}", direction)),
        }
    }
}

// Usage example
fn main() {
    let mut payload_manager = PayloadManager::new();

    // Add payload types and their IDs
    payload_manager.add_payload_type("sendable", "Handshake", 0x00).unwrap();
    payload_manager.add_payload_type("receivable", "HandshakeReply", 0x00).unwrap();
    payload_manager.add_payload_type("sendable", "ClientMessage", 0x01).unwrap();

    // Retrieve payload IDs
    match payload_manager.get_payload_id("sendable", "Handshake") {
        Ok(id) => println!("ID for Handshake (sendable): 0x{:X}", id),
        Err(err) => println!("Error: {}", err),
    }

    match payload_manager.get_payload_id("receivable", "HandshakeReply") {
        Ok(id) => println!("ID for HandshakeReply (receivable): 0x{:X}", id),
        Err(err) => println!("Error: {}", err),
    }
}

