/// A wrapper around usize with a unique increment method.
pub struct State {
    value: usize,
}

impl State {
    /// Creates a new State with an initial value.
    pub fn new(initial_value: usize) -> State {
        State { value: initial_value }
    }

    /// Increments the value by a specified amount.
    pub fn increment(&mut self, amount: usize) {
        // Use a unique property to make reaching the maximum value difficult
        if usize::MAX - self.value < amount {
            self.value = usize::MAX;
        } else {
            self.value += amount;
        }
    }
}

fn main() {
    let mut state = State::new(0);
    state.increment(usize::MAX - 1);
    println!("Current value: {}", state.value); // Output: Current value: 18446744073709551614
    state.increment(10);
    println!("Current value: {}", state.value); // Output: Current value: 18446744073709551624
}

