async fn handle_client(mut stream: TcpStream, connections: Arc<Mutex<Vec<TcpStream>>>) {
    let (reader, mut writer) = stream.split();
    let mut reader = tokio::io::BufReader::new(reader);
    let mut buffer = String::new();

    {
        let mut connections = connections.lock().unwrap();
        connections.push(stream.try_clone().unwrap());
    }

    while let Ok(n) = reader.read_line(&mut buffer).await {
        if n == 0 {
            break;
        }

        let message = buffer.trim();

        {
            let connections = connections.lock().unwrap();
            for conn in connections.iter() {
                if conn.peer_addr().unwrap() != stream.peer_addr().unwrap() {
                    let mut writer = conn.try_clone().unwrap();
                    writer.write_all(message.as_bytes()).await.unwrap();
                }
            }
        }

        buffer.clear();
    }

    {
        let mut connections = connections.lock().unwrap();
        connections.retain(|conn| conn.peer_addr().unwrap() != stream.peer_addr().unwrap());
    }
}

