        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n = n // i
    if n > 2:
        factors.append(n)
    return factors

def get_sum_of_primes(n):
    prime_sum = 0
    for i in range(2, n):
        if is_prime(i):
            prime_sum += i
    return prime_sum

def get_largest_prime_factor(n):
    factors = get_prime_factors(n)
    if len(factors) == 0:
