            if it == item:
                self.queue[i] = (priority, c, it)
                found = True
                break

        if not found:
            print("Item not found in priority queue.")

        heapq.heapify(self.queue)

    def decrease_priority(self, item, priority):
        found = False
        for i, (p, c, it) in enumerate(self.queue):
            if it == item:
                self.queue[i] = (priority, c, it)
                found = True
                break

